{
  "name": "NexusMLM - 10-Level Recharge Utility",
  "description": "A comprehensive MLM platform featuring 10 levels of referrals, mobile recharge utilities, and a robust admin control panel.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

export interface User {
  id: string;
  name: string;
  email: string;
  phone: string;
  referralCode: string;
  referrerId: string | null;
  role: UserRole;
  walletBalance: number;
  totalEarned: number;
  status: 'active' | 'suspended';
  level: number; // For the tree
  joinedAt: string;
}

export interface RechargePlan {
  id: string;
  name: string;
  price: number;
  validity: string;
  data: string;
  calls: string;
  provider: 'Airtel' | 'Jio' | 'Vi' | 'BSNL';
}

export interface Transaction {
  id: string;
  userId: string;
  amount: number;
  type: 'recharge' | 'commission' | 'withdrawal';
  description: string;
  status: 'success' | 'pending' | 'failed';
  createdAt: string;
  fromUserId?: string; // If commission, who triggered it
}

export interface ReferralStat {
  level: number;
  count: number;
  earnings: number;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getSmartInsights = async (userStats: any) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze the following MLM user stats and provide 3 actionable growth tips. Stats: ${JSON.stringify(userStats)}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });
    return JSON.parse(response.text || '{"tips": []}');
  } catch (error) {
    console.error("Gemini Error:", error);
    return { tips: ["Focus on direct referrals", "Host a webinar", "Run a bonus campaign"] };
  }
};

export const getPlanRecommendation = async (usage: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Recommend a mobile recharge plan type (e.g., Heavy Data, Long Validity) for a user who says: "${usage}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            recommendation: { type: Type.STRING },
            reason: { type: Type.STRING }
          }
        }
      }
    });
    return JSON.parse(response.text || '{"recommendation": "Standard Plan", "reason": "Reliable data and calls"}');
  } catch (error) {
    return { recommendation: "Standard Unlimited", reason: "Good balance of value and utility" };
  }
};

import React, { useState, useEffect } from 'react';
import { User, UserRole, Transaction } from './types';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import AdminPanel from './components/AdminPanel';
import { Layout } from './components/Layout';

const INITIAL_USERS: User[] = [
  {
    id: 'admin-1',
    name: 'Nexus Admin',
    email: 'admin@nexus.com',
    phone: '9999999999',
    referralCode: 'ADMIN001',
    referrerId: null,
    role: UserRole.ADMIN,
    walletBalance: 1000000,
    totalEarned: 0,
    status: 'active',
    level: 0,
    joinedAt: new Date().toISOString(),
  }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('nexus_users');
    return saved ? JSON.parse(saved) : INITIAL_USERS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('nexus_transactions');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('nexus_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('nexus_transactions', JSON.stringify(transactions));
  }, [transactions]);

  const handleLogin = (email: string) => {
    const user = users.find(u => u.email === email);
    if (user) {
      if (user.status === 'suspended') {
        alert("Your account is suspended. Contact admin.");
        return;
      }
      setCurrentUser(user);
    } else {
      alert("User not found. Please sign up.");
    }
  };

  const handleSignup = (userData: Partial<User>, referrerCode?: string) => {
    const referrer = users.find(u => u.referralCode === referrerCode);
    const newUser: User = {
      id: `user-${Date.now()}`,
      name: userData.name || 'User',
      email: userData.email || '',
      phone: userData.phone || '',
      referralCode: `NEX${Math.random().toString(36).substring(7).toUpperCase()}`,
      referrerId: referrer ? referrer.id : 'admin-1', // Default to admin if no code
      role: UserRole.USER,
      walletBalance: 0,
      totalEarned: 0,
      status: 'active',
      level: referrer ? referrer.level + 1 : 1,
      joinedAt: new Date().toISOString(),
    };

    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const updateWallet = (userId: string, amount: number, type: Transaction['type'], desc: string, fromId?: string) => {
    setUsers(prev => prev.map(u => {
      if (u.id === userId) {
        return {
          ...u,
          walletBalance: u.walletBalance + amount,
          totalEarned: amount > 0 ? u.totalEarned + amount : u.totalEarned
        };
      }
      return u;
    }));

    const newTx: Transaction = {
      id: `tx-${Date.now()}-${Math.random()}`,
      userId,
      amount,
      type,
      description: desc,
      status: 'success',
      createdAt: new Date().toISOString(),
      fromUserId: fromId
    };
    setTransactions(prev => [newTx, ...prev]);

    // MLM Commission Logic (Up to 10 Levels)
    if (type === 'recharge' && amount < 0) {
      const rechargeAmount = Math.abs(amount);
      const commissionRates = [0.10, 0.05, 0.03, 0.02, 0.01, 0.005, 0.005, 0.005, 0.005, 0.005];

      let currentUserId = userId;
      for (let i = 0; i < 10; i++) {
        const currentUser = users.find(u => u.id === currentUserId);
        if (!currentUser || !currentUser.referrerId) break;

        const referrer = users.find(u => u.id === currentUser.referrerId);
        if (!referrer) break;

        const comm = rechargeAmount * commissionRates[i];
        updateWallet(referrer.id, comm, 'commission', `Level ${i + 1} commission from ${currentUser.name}`, userId);
        currentUserId = referrer.id;
      }
    }
  };

  const adminActions = {
    suspendUser: (id: string) => {
      setUsers(prev => prev.map(u => u.id === id ? { ...u, status: u.status === 'active' ? 'suspended' : 'active' } : u));
    },
    deleteUser: (id: string) => {
      setUsers(prev => prev.filter(u => u.id !== id));
    },
    adjustBalance: (id: string, amount: number) => {
      setUsers(prev => prev.map(u => u.id === id ? { ...u, walletBalance: u.walletBalance + amount } : u));
    }
  };

  if (!currentUser) {
    return <Auth onLogin={handleLogin} onSignup={handleSignup} />;
  }

  return (
    <Layout user={currentUser} onLogout={handleLogout}>
      {currentUser.role === UserRole.ADMIN ? (
        <AdminPanel 
          users={users} 
          transactions={transactions} 
          actions={adminActions} 
        />
      ) : (
        <Dashboard 
          user={currentUser} 
          users={users}
          transactions={transactions.filter(t => t.userId === currentUser.id)} 
          onRecharge={(amount, desc) => updateWallet(currentUser.id, -amount, 'recharge', desc)}
          onAddFunds={(amount) => updateWallet(currentUser.id, amount, 'withdrawal', 'Wallet Add Funds')}
        />
      )}
    </Layout>
  );
};

export default App;

