import React, { useState } from 'react';

interface AuthProps {
  onLogin: (email: string) => void;
  onSignup: (data: any, ref: string) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin, onSignup }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    referralCode: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isLogin) {
      onLogin(formData.email);
    } else {
      onSignup(formData, formData.referralCode);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-100 p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <span className="text-white font-bold text-3xl">N</span>
          </div>
          <h1 className="text-2xl font-bold text-slate-900">Welcome to NexusMLM</h1>
          <p className="text-slate-500">The premier 10-level recharge network</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Full Name</label>
              <input
                type="text"
                required
                className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                placeholder="John Doe"
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
              />
            </div>
          )}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Email Address</label>
            <input
              type="email"
              required
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              placeholder="name@company.com"
              value={formData.email}
              onChange={(e) => setFormData({...formData, email: e.target.value})}
            />
          </div>
          {!isLogin && (
            <>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Phone Number</label>
                <input
                  type="tel"
                  required
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                  placeholder="9876543210"
                  value={formData.phone}
                  onChange={(e) => setFormData({...formData, phone: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Referral Code (Optional)</label>
                <input
                  type="text"
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                  placeholder="NEX123"
                  value={formData.referralCode}
                  onChange={(e) => setFormData({...formData, referralCode: e.target.value})}
                />
              </div>
            </>
          )}

          <button
            type="submit"
            className="w-full py-3 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition-colors shadow-lg"
          >
            {isLogin ? 'Login' : 'Create Account'}
          </button>
        </form>

        <div className="mt-6 text-center">
          <button
            onClick={() => setIsLogin(!isLogin)}
            className="text-indigo-600 font-medium hover:underline"
          >
            {isLogin ? "Don't have an account? Sign up" : "Already have an account? Login"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { User, Transaction, RechargePlan } from '../types';
import { getSmartInsights, getPlanRecommendation } from '../services/geminiService';

const PLANS: RechargePlan[] = [
  { id: 'p1', name: 'Unlimited Daily', price: 299, validity: '28 Days', data: '1.5GB/Day', calls: 'Unlimited', provider: 'Jio' },
  { id: 'p2', name: 'Work From Home', price: 699, validity: '56 Days', data: '2GB/Day', calls: 'Unlimited', provider: 'Airtel' },
  { id: 'p3', name: 'Yearly Value', price: 2999, validity: '365 Days', data: '2.5GB/Day', calls: 'Unlimited', provider: 'Vi' },
];

interface DashboardProps {
  user: User;
  users: User[];
  transactions: Transaction[];
  onRecharge: (amount: number, desc: string) => void;
  onAddFunds: (amount: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, users, transactions, onRecharge, onAddFunds }) => {
  const [activeTab, setActiveTab] = useState<'home' | 'recharge' | 'referrals' | 'wallet'>('home');
  const [insights, setInsights] = useState<string[]>([]);
  const [usageInput, setUsageInput] = useState('');
  const [recommendation, setRecommendation] = useState<any>(null);

  useEffect(() => {
    const fetchInsights = async () => {
      const res = await getSmartInsights({ balance: user.walletBalance, total: user.totalEarned });
      setInsights(res.tips);
    };
    fetchInsights();
  }, []);

  const handleRecommend = async () => {
    if (!usageInput) return;
    const res = await getPlanRecommendation(usageInput);
    setRecommendation(res);
  };

  const getDirectReferrals = () => users.filter(u => u.referrerId === user.id);

  // Simple tree calculation for 10 levels
  const getDownlineCount = () => {
    const counts = new Array(10).fill(0);
    const getLevels = (parentId: string, currentLevel: number) => {
      if (currentLevel > 10) return;
      const children = users.filter(u => u.referrerId === parentId);
      counts[currentLevel - 1] += children.length;
      children.forEach(child => getLevels(child.id, currentLevel + 1));
    };
    getLevels(user.id, 1);
    return counts;
  };

  const downlineLevels = getDownlineCount();

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Wallet Balance</p>
          <p className="text-3xl font-bold text-slate-900 mt-1">₹{user.walletBalance.toFixed(2)}</p>
          <button onClick={() => onAddFunds(500)} className="mt-4 text-sm text-indigo-600 font-semibold hover:underline">Add Funds (Quick ₹500)</button>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Total MLM Earnings</p>
          <p className="text-3xl font-bold text-emerald-600 mt-1">₹{user.totalEarned.toFixed(2)}</p>
          <p className="text-xs text-slate-400 mt-1">From 10 Level Matrix</p>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Referral Code</p>
          <p className="text-2xl font-mono font-bold text-indigo-600 mt-1">{user.referralCode}</p>
          <button className="mt-4 text-sm text-slate-400 font-semibold">Copy Code</button>
        </div>
      </div>

      <div className="flex border-b border-slate-200">
        {(['home', 'recharge', 'referrals', 'wallet'] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-4 text-sm font-medium capitalize border-b-2 transition-colors ${
              activeTab === tab ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-700'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      <div className="mt-6">
        {activeTab === 'home' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-bold mb-4">Recent Transactions</h3>
              <div className="space-y-3">
                {transactions.length > 0 ? transactions.map(tx => (
                  <div key={tx.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg">
                    <div>
                      <p className="text-sm font-semibold">{tx.description}</p>
                      <p className="text-xs text-slate-500">{new Date(tx.createdAt).toLocaleString()}</p>
                    </div>
                    <p className={`font-bold ${tx.amount > 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {tx.amount > 0 ? '+' : ''}{tx.amount.toFixed(2)}
                    </p>
                  </div>
                )) : <p className="text-slate-400 text-center py-8">No transactions yet</p>}
              </div>
            </div>

            <div className="space-y-6">
              <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100">
                <h3 className="text-indigo-900 font-bold mb-3 flex items-center gap-2">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  AI Growth Insights
                </h3>
                <ul className="space-y-2">
                  {insights.map((tip, i) => (
                    <li key={i} className="text-sm text-indigo-700 flex gap-2">
                      <span className="font-bold">{i+1}.</span> {tip}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'recharge' && (
          <div className="space-y-8">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-bold mb-4">Smart Plan Assistant</h3>
              <p className="text-sm text-slate-500 mb-4">Tell us your data usage needs and let AI suggest a plan.</p>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={usageInput}
                  onChange={(e) => setUsageInput(e.target.value)}
                  placeholder="I watch a lot of Netflix and need long validity..."
                  className="flex-1 px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                />
                <button 
                  onClick={handleRecommend}
                  className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  Analyze
                </button>
              </div>
              {recommendation && (
                <div className="mt-4 p-4 bg-emerald-50 border border-emerald-100 rounded-lg">
                  <p className="text-emerald-800 font-bold">Recommendation: {recommendation.recommendation}</p>
                  <p className="text-emerald-600 text-sm mt-1">{recommendation.reason}</p>
                </div>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {PLANS.map(plan => (
                <div key={plan.id} className="bg-white border p-6 rounded-2xl hover:shadow-md transition-shadow">
                  <div className="flex justify-between items-start mb-4">
                    <span className="px-2 py-1 bg-slate-100 text-xs font-bold rounded uppercase">{plan.provider}</span>
                    <span className="text-2xl font-bold text-indigo-600">₹{plan.price}</span>
                  </div>
                  <h4 className="font-bold text-lg mb-1">{plan.name}</h4>
                  <div className="space-y-1 text-sm text-slate-500 mb-6">
                    <p>Validity: {plan.validity}</p>
                    <p>Data: {plan.data}</p>
                    <p>Calls: {plan.calls}</p>
                  </div>
                  <button 
                    disabled={user.walletBalance < plan.price}
                    onClick={() => onRecharge(plan.price, `Recharge: ${plan.name} (${plan.provider})`)}
                    className={`w-full py-2 rounded-lg font-semibold transition-colors ${
                      user.walletBalance >= plan.price 
                        ? 'bg-slate-900 text-white hover:bg-black' 
                        : 'bg-slate-100 text-slate-400 cursor-not-allowed'
                    }`}
                  >
                    {user.walletBalance >= plan.price ? 'Recharge Now' : 'Insufficient Balance'}
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'referrals' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="text-lg font-bold mb-4">Your 10-Level Matrix</h3>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                  {downlineLevels.map((count, i) => (
                    <div key={i} className="p-4 bg-slate-50 rounded-xl text-center">
                      <p className="text-xs text-slate-400 font-bold uppercase mb-1">Level {i+1}</p>
                      <p className="text-2xl font-bold text-slate-900">{count}</p>
                    </div>
                  ))}
                </div>
             </div>

             <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="text-lg font-bold mb-4">Direct Referrals (Level 1)</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="border-b text-slate-400 text-sm uppercase">
                        <th className="pb-3 px-2">Name</th>
                        <th className="pb-3 px-2">Phone</th>
                        <th className="pb-3 px-2">Joined</th>
                        <th className="pb-3 px-2">Earnings Generated</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y text-sm">
                      {getDirectReferrals().length > 0 ? getDirectReferrals().map(ref => (
