import React, { useState, useEffect } from 'react';
import { User, UserRole, Transaction, Product, Order, MLMConfig, Wallets } from './types';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import AdminPanel from './components/AdminPanel';
import VendorPanel from './components/VendorPanel';
import { Layout } from './components/Layout';

const DEFAULT_MLM_CONFIG: MLMConfig = {
  rechargeCommission: [0.05, 0.02, 0.01, 0.005, 0.005, 0.002, 0.002, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001],
  productCommission: [0.10, 0.05, 0.03, 0.02, 0.01, 0.01, 0.01, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005, 0.005],
  tdsRate: 0.05,
  serviceCharge: 0.05
};

const INITIAL_PRODUCTS: Product[] = [
  { id: 'p1', vendorId: 'v1', name: 'Premium Herbal Tea', description: 'Natural detox tea', price: 499, mrp: 699, category: 'Herbal', stock: 100, image: '☕', mlmPoints: 100 },
  { id: 'p2', vendorId: 'v1', name: 'Aloe Vera Gel', description: 'Pure organic aloe', price: 299, mrp: 399, category: 'Wellness', stock: 50, image: '🌿', mlmPoints: 50 },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(() => JSON.parse(localStorage.getItem('spay_users') || '[]'));
  const [products, setProducts] = useState<Product[]>(() => JSON.parse(localStorage.getItem('spay_products') || JSON.stringify(INITIAL_PRODUCTS)));
  const [orders, setOrders] = useState<Order[]>(() => JSON.parse(localStorage.getItem('spay_orders') || '[]'));
  const [transactions, setTransactions] = useState<Transaction[]>(() => JSON.parse(localStorage.getItem('spay_tx') || '[]'));
  const [mlmConfig, setMlmConfig] = useState<MLMConfig>(DEFAULT_MLM_CONFIG);

  useEffect(() => {
    if (users.length === 0) {
      const admin: User = {
        id: 'admin-0',
        name: 'System Admin',
        email: 'admin@spay.com',
        password: 'admin123',
        phone: '0000000000',
        referralCode: 'SPAY001',
        referrerId: null,
        role: UserRole.ADMIN,
        wallets: { main: 1000000, commission: 0, cashback: 0, recharge: 1000000 },
        totalEarned: 0,
        status: 'active',
        level: 0,
        joinedAt: new Date().toISOString()
      };
      setUsers([admin]);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('spay_users', JSON.stringify(users));
    localStorage.setItem('spay_products', JSON.stringify(products));
    localStorage.setItem('spay_orders', JSON.stringify(orders));
    localStorage.setItem('spay_tx', JSON.stringify(transactions));
  }, [users, products, orders, transactions]);

  const handleTransaction = (userId: string, amount: number, wallet: keyof Wallets, type: Transaction['type'], desc: string) => {
    setUsers(prev => prev.map(u => {
      if (u.id === userId) {
        const newWallets = { ...u.wallets, [wallet]: (u.wallets[wallet] || 0) + amount };
        return { ...u, wallets: newWallets, totalEarned: amount > 0 && wallet === 'commission' ? u.totalEarned + amount : u.totalEarned };
      }
      return u;
    }));
    setTransactions(prev => [{
      id: `TX${Date.now()}`, userId, amount, walletType: wallet, type, description: desc, status: 'success', createdAt: new Date().toISOString()
    }, ...prev]);
  };

  const distributeCommission = (triggerUserId: string, baseAmount: number, commissionType: 'recharge' | 'product') => {
    const rates = commissionType === 'recharge' ? mlmConfig.rechargeCommission : mlmConfig.productCommission;
    let currentUserId = triggerUserId;

    for (let i = 0; i < 20; i++) {
      const triggerUser = users.find(u => u.id === currentUserId);
      if (!triggerUser || !triggerUser.referrerId) break;

      const referrer = users.find(u => u.id === triggerUser.referrerId);
      if (!referrer) break;

      const rawCommission = baseAmount * rates[i];
      const netCommission = rawCommission * (1 - mlmConfig.tdsRate - mlmConfig.serviceCharge);

      handleTransaction(referrer.id, netCommission, 'commission', 'commission', `Level ${i + 1} ${commissionType} income from ${triggerUser.name}`);
      currentUserId = referrer.id;
    }
  };

  const handleRecharge = (userId: string, amount: number, service: string) => {
    const user = users.find(u => u.id === userId);
    if (!user || user.wallets.main < amount) return alert('Insufficient Balance');

    handleTransaction(userId, -amount, 'main', 'recharge', `${service} Payment`);
    const cashback = amount * 0.02;
    handleTransaction(userId, cashback, 'cashback', 'recharge', `Cashback for ${service}`);
    distributeCommission(userId, amount, 'recharge');
  };

  const placeOrder = (userId: string, productId: string) => {
    const user = users.find(u => u.id === userId);
    const product = products.find(p => p.id === productId);
    if (!user || !product || user.wallets.main < product.price) return alert('Cannot place order');

    const newOrder: Order = {
      id: `ORD${Date.now()}`, userId, vendorId: product.vendorId, productId, amount: product.price, status: 'pending', createdAt: new Date().toISOString()
    };
    setOrders(prev => [...prev, newOrder]);
    handleTransaction(userId, -product.price, 'main', 'shopping', `Purchase: ${product.name}`);

    handleTransaction(product.vendorId, product.price * 0.8, 'vendor' as any, 'shopping', `Order Sale: ${product.name}`);
    distributeCommission(userId, product.price, 'product');
  };

  const handleLogin = (email: string, password?: string) => {
    const u = users.find(user => 
      user.email.toLowerCase() === email.toLowerCase() && 
      (user.password === password)
    );
    if (u) {
      setCurrentUser(u);
    } else {
      alert('Invalid ID or Password');
    }
  };

  const handleSignup = (data: any) => {
    if (users.some(u => u.email.toLowerCase() === data.email.toLowerCase())) {
      alert('Email already registered');
      return;
    }

    const ref = users.find(u => u.referralCode === data.referralCode) || users[0];
    const newUser: User = {
      ...data,
      id: `U${Date.now()}`, 
      role: UserRole.USER, 
      referralCode: `SP${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      referrerId: ref.id, 
      level: ref.level + 1, 
      wallets: { main: 0, commission: 0, cashback: 0, recharge: 0 },
      totalEarned: 0, 
      status: 'active', 
      joinedAt: new Date().toISOString()
    };
    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
  };

  if (!currentUser) return <Auth onLogin={handleLogin} onSignup={handleSignup} />;

  return (
    <Layout user={currentUser} onLogout={() => setCurrentUser(null)}>
      {currentUser.role === UserRole.ADMIN ? (
        <AdminPanel users={users} transactions={transactions} config={mlmConfig} onUpdateConfig={setMlmConfig} />
      ) : currentUser.role === UserRole.VENDOR ? (
        <VendorPanel user={currentUser} products={products} orders={orders} onAddProduct={(p) => setProducts([...products, p])} />
      ) : (
        <Dashboard 
          user={currentUser} 
          users={users} 
          products={products}
          transactions={transactions.filter(t => t.userId === currentUser.id)} 
          onRecharge={handleRecharge}
          onOrder={placeOrder}
        />
      )}
    </Layout>
  );
};

export default App;

