export interface MLMConfig {
  rechargeCommission: number[]; // 10 levels
  productCommission: number[]; // 10 levels
  packageCommission: number[]; // 10 levels for the 249 package
  packagePrice: number;
  tdsRate: number;
  serviceCharge: number;
}

import React, { useState, useEffect } from 'react';
import { User, UserRole, Transaction, Product, Order, MLMConfig, Wallets } from './types';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import AdminPanel from './components/AdminPanel';
import VendorPanel from './components/VendorPanel';
import { Layout } from './components/Layout';

const DEFAULT_MLM_CONFIG: MLMConfig = {
  rechargeCommission: [0.05, 0.02, 0.01, 0.005, 0.005, 0.002, 0.002, 0.001, 0.001, 0.001],
  productCommission: [0.10, 0.05, 0.03, 0.02, 0.01, 0.01, 0.01, 0.005, 0.005, 0.005],
  packageCommission: [50, 20, 10, 5, 5, 2, 2, 1, 1, 1], // Fixed amounts for package
  packagePrice: 249,
  tdsRate: 0.05,
  serviceCharge: 0.05
};

const INITIAL_PRODUCTS: Product[] = [
  { id: 'p1', vendorId: 'v1', name: 'Premium Herbal Tea', description: 'Natural detox tea', price: 499, mrp: 699, category: 'Herbal', stock: 100, image: '☕', mlmPoints: 100 },
  { id: 'p2', vendorId: 'v1', name: 'Aloe Vera Gel', description: 'Pure organic aloe', price: 299, mrp: 399, category: 'Wellness', stock: 50, image: '🌿', mlmPoints: 50 },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(() => JSON.parse(localStorage.getItem('spay_users') || '[]'));
  const [products, setProducts] = useState<Product[]>(() => JSON.parse(localStorage.getItem('spay_products') || JSON.stringify(INITIAL_PRODUCTS)));
  const [orders, setOrders] = useState<Order[]>(() => JSON.parse(localStorage.getItem('spay_orders') || '[]'));
  const [transactions, setTransactions] = useState<Transaction[]>(() => JSON.parse(localStorage.getItem('spay_tx') || '[]'));
  const [mlmConfig, setMlmConfig] = useState<MLMConfig>(() => JSON.parse(localStorage.getItem('spay_config') || JSON.stringify(DEFAULT_MLM_CONFIG)));

  useEffect(() => {
    if (users.length === 0) {
      const admin: User = {
        id: 'admin-0',
        name: 'System Admin',
        email: 'admin@spay.com',
        password: 'admin123',
        phone: '0000000000',
        referralCode: 'SPAY001',
        referrerId: null,
        role: UserRole.ADMIN,
        wallets: { main: 1000000, commission: 0, cashback: 0, recharge: 1000000 },
        totalEarned: 0,
        status: 'active',
        level: 0,
        joinedAt: new Date().toISOString(),
        isActivated: true
      };
      setUsers([admin]);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('spay_users', JSON.stringify(users));
    localStorage.setItem('spay_products', JSON.stringify(products));
    localStorage.setItem('spay_orders', JSON.stringify(orders));
    localStorage.setItem('spay_tx', JSON.stringify(transactions));
    localStorage.setItem('spay_config', JSON.stringify(mlmConfig));
  }, [users, products, orders, transactions, mlmConfig]);

  const handleTransaction = (userId: string, amount: number, wallet: keyof Wallets, type: Transaction['type'], desc: string) => {
    setUsers(prev => prev.map(u => {
      if (u.id === userId) {
        const newWallets = { ...u.wallets, [wallet]: (u.wallets[wallet] || 0) + amount };
        return { ...u, wallets: newWallets, totalEarned: amount > 0 && wallet === 'commission' ? u.totalEarned + amount : u.totalEarned };
      }
      return u;
    }));
    setTransactions(prev => [{
      id: `TX${Date.now()}`, userId, amount, walletType: wallet, type, description: desc, status: 'success', createdAt: new Date().toISOString()
    }, ...prev]);
  };

  const distributeCommission = (triggerUserId: string, baseAmount: number, commissionType: 'recharge' | 'product' | 'package') => {
    const rates = commissionType === 'recharge' ? mlmConfig.rechargeCommission : 
                  commissionType === 'product' ? mlmConfig.productCommission : 
                  mlmConfig.packageCommission;

    let currentUserId = triggerUserId;

    for (let i = 0; i < 10; i++) {
      const triggerUser = users.find(u => u.id === currentUserId);
      if (!triggerUser || !triggerUser.referrerId) break;

      const referrer = users.find(u => u.id === triggerUser.referrerId);
      if (!referrer) break;

      // For package, rates is an array of fixed amounts. For others, it's percentages.
      const rawCommission = commissionType === 'package' ? rates[i] : (baseAmount * rates[i]);
      const netCommission = rawCommission * (1 - mlmConfig.tdsRate - mlmConfig.serviceCharge);

      handleTransaction(referrer.id, netCommission, 'commission', 'commission', `Level ${i + 1} ${commissionType} income from ${triggerUser.name}`);
      currentUserId = referrer.id;
    }
  };

  const handleActivateAccount = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (!user) return;
    if (user.wallets.main < mlmConfig.packagePrice) return alert('Insufficient Balance to Activate. Please add funds first.');

    handleTransaction(userId, -mlmConfig.packagePrice, 'main', 'activation', `Package Activation Fee`);
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, isActivated: true, status: 'active' } : u));
    distributeCommission(userId, mlmConfig.packagePrice, 'package');
    alert('Account Activated Successfully! You are now eligible for commissions.');
  };

  const handleTransfer = (senderId: string, recipientEmail: string, amount: number) => {
    const sender = users.find(u => u.id === senderId);
    const recipient = users.find(u => u.email.toLowerCase() === recipientEmail.toLowerCase());

    if (!sender || sender.wallets.main < amount) return alert('Insufficient balance');
    if (!recipient) return alert('Recipient not found');
    if (sender.id === recipient.id) return alert('Cannot transfer to yourself');

    handleTransaction(senderId, -amount, 'main', 'withdrawal', `Transfer to ${recipient.name}`);
    handleTransaction(recipient.id, amount, 'main', 'add_funds', `Transfer from ${sender.name}`);
    alert('Transfer successful!');
  };

  const handleRecharge = (userId: string, amount: number, service: string) => {
    const user = users.find(u => u.id === userId);
    if (!user || !user.isActivated) return alert('Please activate your account first to use utility services.');
    if (user.wallets.main < amount) return alert('Insufficient Balance');

    handleTransaction(userId, -amount, 'main', 'recharge', `${service} Payment`);
    const cashback = amount * 0.02;
    handleTransaction(userId, cashback, 'cashback', 'recharge', `Cashback for ${service}`);
    distributeCommission(userId, amount, 'recharge');
  };

  const placeOrder = (userId: string, productId: string) => {
    const user = users.find(u => u.id === userId);
    const product = products.find(p => p.id === productId);
    if (!user || !user.isActivated) return alert('Please activate your account first.');
    if (!product || user.wallets.main < product.price) return alert('Cannot place order');

    handleTransaction(userId, -product.price, 'main', 'shopping', `Purchase: ${product.name}`);
    handleTransaction(product.vendorId, product.price * 0.8, 'vendor' as any, 'shopping', `Order Sale: ${product.name}`);
    distributeCommission(userId, product.price, 'product');
  };

  const handleLogin = (email: string, password?: string) => {
    const u = users.find(user => 
      user.email.toLowerCase() === email.toLowerCase() && user.password === password
    );
    if (u) setCurrentUser(u);
    else alert('Invalid ID or Password');
  };

  const handleSignup = (data: any) => {
    if (users.some(u => u.email.toLowerCase() === data.email.toLowerCase())) return alert('Email already registered');

    const ref = users.find(u => u.referralCode === data.referralCode) || users[0];
    const newUser: User = {
      ...data,
      id: `U${Date.now()}`, 
      role: UserRole.USER, 
      referralCode: `SP${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      referrerId: ref.id, 
      level: ref.level + 1, 
      wallets: { main: 0, commission: 0, cashback: 0, recharge: 0 },
      totalEarned: 0, 
      status: 'pending', 
      isActivated: false,
      joinedAt: new Date().toISOString()
    };
    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
  };

  if (!currentUser) return <Auth onLogin={handleLogin} onSignup={handleSignup} />;

  const activeUser = users.find(u => u.id === currentUser.id) || currentUser;

  return (
    <Layout user={activeUser} onLogout={() => setCurrentUser(null)}>
      {activeUser.role === UserRole.ADMIN ? (
        <AdminPanel users={users} transactions={transactions} config={mlmConfig} onUpdateConfig={setMlmConfig} />
      ) : activeUser.role === UserRole.VENDOR ? (
        <VendorPanel user={activeUser} products={products} orders={orders} onAddProduct={(p) => setProducts([...products, p])} />
      ) : (
        <Dashboard 
          user={activeUser} 
          users={users} 
          products={products}
          transactions={transactions.filter(t => t.userId === activeUser.id)} 
          onRecharge={handleRecharge}
          onOrder={placeOrder}
          onTransfer={handleTransfer}
          onActivate={handleActivateAccount}
          packagePrice={mlmConfig.packagePrice}
        />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { User, Transaction, Product } from '../types';

interface DashboardProps {
  user: User;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  onRecharge: (userId: string, amt: number, service: string) => void;
  onOrder: (userId: string, pId: string) => void;
  onTransfer: (senderId: string, recipientEmail: string, amount: number) => void;
  onActivate: (userId: string) => void;
  packagePrice: number;
}

const Dashboard: React.FC<DashboardProps> = ({ user, users, products, transactions, onRecharge, onOrder, onTransfer, onActivate, packagePrice }) => {
  const [tab, setTab] = useState<'home' | 'utility' | 'shop' | 'transfer' | 'mlm'>('home');
  const [transferData, setTransferData] = useState({ email: '', amount: '' });

  // Compute Stats
  const todayDateString = new Date().toISOString().split('T')[0];

  const todayIncome = useMemo(() => {
    return transactions
      .filter(tx => tx.createdAt.startsWith(todayDateString) && tx.amount > 0 && tx.walletType === 'commission')
      .reduce((sum, tx) => sum + tx.amount, 0);
  }, [transactions, todayDateString]);

  // Recursively find all downline members
  const myDownline = useMemo(() => {
    const findDownline = (uId: string): User[] => {
      const directs = users.filter(u => u.referrerId === uId);
      let fullList = [...directs];
      directs.forEach(d => {
        fullList = [...fullList, ...findDownline(d.id)];
      });
      return fullList;
    };
    return findDownline(user.id);
  }, [users, user.id]);

  const activeMembersCount = useMemo(() => myDownline.filter(u => u.isActivated).length, [myDownline]);
  const todayJoiningsCount = useMemo(() => myDownline.filter(u => u.joinedAt.startsWith(todayDateString)).length, [myDownline, todayDateString]);

  const stats = [
    { label: 'Total Income', val: `₹${user.totalEarned.toFixed(2)}`, color: 'text-blue-600' },
    { label: 'Today Income', val: `₹${todayIncome.toFixed(2)}`, color: 'text-emerald-600' },
    { label: 'Total Active Team', val: activeMembersCount.toString(), color: 'text-indigo-600' },
    { label: 'Today Joinings', val: todayJoiningsCount.toString(), color: 'text-orange-600' },
    { label: 'Main Wallet', val: `₹${user.wallets.main.toFixed(2)}`, color: 'text-slate-900' },
  ];

  const handleTransferSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const amt = parseFloat(transferData.amount);
    if (isNaN(amt) || amt <= 0) return alert('Enter a valid amount');
    onTransfer(user.id, transferData.email, amt);
    setTransferData({ email: '', amount: '' });
  };

  return (
    <div className="space-y-6">
      {!user.isActivated && (
        <div className="bg-red-50 border border-red-200 p-6 rounded-2xl flex flex-col md:flex-row items-center justify-between gap-4">
           <div>
              <h3 className="text-red-800 font-bold text-lg">Account Inactive</h3>
              <p className="text-red-600 text-sm">Purchase the Activation Package for ₹{packagePrice} to unlock earnings and services.</p>
           </div>
           <button 
             onClick={() => onActivate(user.id)}
             className="bg-red-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg hover:bg-red-700 transition-all"
           >
             Activate Now (₹{packagePrice})
           </button>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {stats.map(s => (
          <div key={s.label} className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{s.label}</p>
            <p className={`text-xl font-black mt-1 ${s.color}`}>{s.val}</p>
          </div>
        ))}
      </div>

      <nav className="flex gap-1 bg-slate-200/50 p-1 rounded-lg w-fit overflow-x-auto">
        {['home', 'utility', 'shop', 'transfer', 'mlm'].map(t => (
          <button 
            key={t} onClick={() => setTab(t as any)}
            className={`px-6 py-2 rounded-md text-sm font-bold transition-all whitespace-nowrap ${tab === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200'}`}
          >
            {t.toUpperCase()}
          </button>
        ))}
      </nav>

      {tab === 'home' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
            <h3 className="text-lg font-bold mb-4">Activity Stream</h3>
            <div className="space-y-3">
              {transactions.slice(0, 8).map(tx => (
                <div key={tx.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${tx.amount > 0 ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                      {tx.type[0].toUpperCase()}
