import React, { useState, useEffect } from 'react';
import { User, UserRole, Transaction, Product, Order, MLMConfig, Wallets, PaymentRequest } from './types';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import AdminPanel from './components/AdminPanel';
import VendorPanel from './components/VendorPanel';
import { Layout } from './components/Layout';

const DEFAULT_MLM_CONFIG: MLMConfig = {
  rechargeCommission: [0.05, 0.02, 0.01, 0.005, 0.005, 0.002, 0.002, 0.001, 0.001, 0.001],
  productCommission: [0.10, 0.05, 0.03, 0.02, 0.01, 0.01, 0.01, 0.005, 0.005, 0.005],
  packageCommission: [50, 20, 10, 5, 5, 2, 2, 1, 1, 1],
  packagePrice: 249,
  tdsRate: 0.05,
  serviceCharge: 0.05,
  qrCode: '' // Initially empty
};

const INITIAL_PRODUCTS: Product[] = [
  { id: 'p1', vendorId: 'v1', name: 'Premium Herbal Tea', description: 'Natural detox tea', price: 499, mrp: 699, category: 'Herbal', stock: 100, image: '☕', mlmPoints: 100 },
  { id: 'p2', vendorId: 'v1', name: 'Aloe Vera Gel', description: 'Pure organic aloe', price: 299, mrp: 399, category: 'Wellness', stock: 50, image: '🌿', mlmPoints: 50 },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(() => JSON.parse(localStorage.getItem('spay_users') || '[]'));
  const [products, setProducts] = useState<Product[]>(() => JSON.parse(localStorage.getItem('spay_products') || JSON.stringify(INITIAL_PRODUCTS)));
  const [orders, setOrders] = useState<Order[]>(() => JSON.parse(localStorage.getItem('spay_orders') || '[]'));
  const [transactions, setTransactions] = useState<Transaction[]>(() => JSON.parse(localStorage.getItem('spay_tx') || '[]'));
  const [mlmConfig, setMlmConfig] = useState<MLMConfig>(() => JSON.parse(localStorage.getItem('spay_config') || JSON.stringify(DEFAULT_MLM_CONFIG)));
  const [paymentRequests, setPaymentRequests] = useState<PaymentRequest[]>(() => JSON.parse(localStorage.getItem('spay_payments') || '[]'));

  useEffect(() => {
    if (users.length === 0) {
      const admin: User = {
        id: 'admin-0',
        name: 'System Admin',
        email: 'admin@spay.com',
        password: 'admin123',
        phone: '0000000000',
        referralCode: 'SPAY001',
        referrerId: null,
        role: UserRole.ADMIN,
        wallets: { main: 1000000, commission: 0, cashback: 0, recharge: 1000000 },
        totalEarned: 0,
        status: 'active',
        level: 0,
        joinedAt: new Date().toISOString(),
        isActivated: true
      };
      setUsers([admin]);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('spay_users', JSON.stringify(users));
    localStorage.setItem('spay_products', JSON.stringify(products));
    localStorage.setItem('spay_orders', JSON.stringify(orders));
    localStorage.setItem('spay_tx', JSON.stringify(transactions));
    localStorage.setItem('spay_config', JSON.stringify(mlmConfig));
    localStorage.setItem('spay_payments', JSON.stringify(paymentRequests));
  }, [users, products, orders, transactions, mlmConfig, paymentRequests]);

  const handleTransaction = (userId: string, amount: number, wallet: keyof Wallets, type: Transaction['type'], desc: string) => {
    setUsers(prev => prev.map(u => {
      if (u.id === userId) {
        const newWallets = { ...u.wallets, [wallet]: (u.wallets[wallet] || 0) + amount };
        return { ...u, wallets: newWallets, totalEarned: (amount > 0 && (wallet === 'commission' || wallet === 'cashback')) ? u.totalEarned + amount : u.totalEarned };
      }
      return u;
    }));
    setTransactions(prev => [{
      id: `TX${Date.now()}`, userId, amount, walletType: wallet, type, description: desc, status: 'success', createdAt: new Date().toISOString()
    }, ...prev]);
  };

  // Logic to deduct from Recharge wallet first, then Main if needed
  const spendFunds = (userId: string, amount: number, type: Transaction['type'], desc: string) => {
    const user = users.find(u => u.id === userId);
    if (!user) return false;

    if (user.wallets.recharge >= amount) {
      handleTransaction(userId, -amount, 'recharge', type, desc);
      return true;
    } else if (user.wallets.main >= amount) {
      handleTransaction(userId, -amount, 'main', type, desc);
      return true;
    }
    return false;
  };

  const distributeCommission = (triggerUserId: string, baseAmount: number, commissionType: 'recharge' | 'product' | 'package') => {
    const rates = commissionType === 'recharge' ? mlmConfig.rechargeCommission : 
                  commissionType === 'product' ? mlmConfig.productCommission : 
                  mlmConfig.packageCommission;

    let currentUserId = triggerUserId;
    for (let i = 0; i < 10; i++) {
      const triggerUser = users.find(u => u.id === currentUserId);
      if (!triggerUser || !triggerUser.referrerId) break;
      const referrer = users.find(u => u.id === triggerUser.referrerId);
      if (!referrer) break;

      const rawCommission = commissionType === 'package' ? rates[i] : (baseAmount * rates[i]);
      const netCommission = rawCommission * (1 - mlmConfig.tdsRate - mlmConfig.serviceCharge);
      handleTransaction(referrer.id, netCommission, 'commission', 'commission', `Level ${i + 1} ${commissionType} income from ${triggerUser.name}`);
      currentUserId = referrer.id;
    }
  };

  const handleActivateAccount = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (!user) return;
    if (spendFunds(userId, mlmConfig.packagePrice, 'activation', 'Package Activation Fee')) {
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, isActivated: true, status: 'active' } : u));
      distributeCommission(userId, mlmConfig.packagePrice, 'package');
      alert('Account Activated Successfully!');
    } else {
      alert('Insufficient Balance. Add funds to Recharge Wallet.');
    }
  };

  const handleTransfer = (senderId: string, recipientEmail: string, amount: number) => {
    const recipient = users.find(u => u.email.toLowerCase() === recipientEmail.toLowerCase());
    if (!recipient) return alert('Recipient not found');
    if (senderId === recipient.id) return alert('Cannot transfer to yourself');

    if (spendFunds(senderId, amount, 'withdrawal', `Transfer to ${recipient.name}`)) {
      handleTransaction(recipient.id, amount, 'recharge', 'add_funds', `Transfer from user`);
      alert('Transfer successful!');
    } else {
      alert('Insufficient balance');
    }
  };

  const handleRecharge = (userId: string, amount: number, service: string) => {
    const user = users.find(u => u.id === userId);
    if (!user || !user.isActivated) return alert('Please activate your account first.');
    if (spendFunds(userId, amount, 'recharge', `${service} Payment`)) {
      const cashback = amount * 0.02;
      handleTransaction(userId, cashback, 'cashback', 'recharge', `Cashback for ${service}`);
      distributeCommission(userId, amount, 'recharge');
      alert(`${service} recharge successful!`);
    } else {
      alert('Insufficient Balance');
    }
  };

  const placeOrder = (userId: string, productId: string) => {
    const user = users.find(u => u.id === userId);
    const product = products.find(p => p.id === productId);
    if (!user || !user.isActivated) return alert('Please activate your account first.');
    if (!product) return alert('Product not found');

    if (spendFunds(userId, product.price, 'shopping', `Purchase: ${product.name}`)) {
      handleTransaction(product.vendorId, product.price * 0.8, 'vendor' as any, 'shopping', `Order Sale: ${product.name}`);
      distributeCommission(userId, product.price, 'product');
      alert('Order placed successfully!');
    } else {
      alert('Insufficient Balance');
    }
  };

  const handleAddMoneyRequest = (data: { amount: number, utr: string, screenshot: string }) => {
    if (!currentUser) return;
    const newRequest: PaymentRequest = {
      id: `PAY${Date.now()}`,
      userId: currentUser.id,
      userName: currentUser.name,
      amount: data.amount,
      utr: data.utr,
      screenshot: data.screenshot,
      status: 'pending',
      createdAt: new Date().toISOString()
    };
    setPaymentRequests(prev => [newRequest, ...prev]);
    alert('Request submitted! Funds will be added after admin verification.');
  };

  const handleApprovePayment = (requestId: string) => {
    const req = paymentRequests.find(r => r.id === requestId);
    if (!req || req.status !== 'pending') return;

    handleTransaction(req.userId, req.amount, 'recharge', 'add_funds', `Approved Add Money: UTR ${req.utr}`);
    setPaymentRequests(prev => prev.map(r => r.id === requestId ? { ...r, status: 'approved' } : r));
    alert('Payment Approved!');
  };

  const handleLogin = (email: string, password?: string) => {
    const u = users.find(user => user.email.toLowerCase() === email.toLowerCase() && user.password === password);
    if (u) setCurrentUser(u);
    else alert('Invalid credentials');
  };

  const handleSignup = (data: any) => {
    if (users.some(u => u.email.toLowerCase() === data.email.toLowerCase())) return alert('Email taken');
    const ref = users.find(u => u.referralCode === data.referralCode) || users[0];
    const newUser: User = {
      ...data, id: `U${Date.now()}`, role: UserRole.USER, 
      referralCode: `SP${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      referrerId: ref.id, level: ref.level + 1, wallets: { main: 0, commission: 0, cashback: 0, recharge: 0 },
      totalEarned: 0, status: 'pending', isActivated: false, joinedAt: new Date().toISOString()
    };
    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
  };

  if (!currentUser) return <Auth onLogin={handleLogin} onSignup={handleSignup} />;

  const activeUser = users.find(u => u.id === currentUser.id) || currentUser;

  return (
    <Layout user={activeUser} onLogout={() => setCurrentUser(null)}>
      {activeUser.role === UserRole.ADMIN ? (
        <AdminPanel 
          users={users} 
          transactions={transactions} 
          config={mlmConfig} 
          onUpdateConfig={setMlmConfig}
          paymentRequests={paymentRequests}
          onApprovePayment={handleApprovePayment}
        />
      ) : activeUser.role === UserRole.VENDOR ? (
        <VendorPanel user={activeUser} products={products} orders={orders} onAddProduct={(p) => setProducts([...products, p])} />
      ) : (
        <Dashboard 
          user={activeUser} 
          users={users} 
          products={products}
          transactions={transactions.filter(t => t.userId === activeUser.id)} 
          onRecharge={handleRecharge}
          onOrder={placeOrder}
          onTransfer={handleTransfer}
          onActivate={handleActivateAccount}
          packagePrice={mlmConfig.packagePrice}
          qrCode={mlmConfig.qrCode}
          onAddMoney={handleAddMoneyRequest}
          paymentRequests={paymentRequests.filter(r => r.userId === activeUser.id)}
        />
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { User, Transaction, MLMConfig, UserRole, PaymentRequest } from '../types';

interface AdminProps {
  users: User[];
  transactions: Transaction[];
  config: MLMConfig;
  onUpdateConfig: (c: MLMConfig) => void;
  paymentRequests: PaymentRequest[];
  onApprovePayment: (id: string) => void;
}

const AdminPanel: React.FC<AdminProps> = ({ users, transactions, config, onUpdateConfig, paymentRequests, onApprovePayment }) => {
  const [activeTab, setActiveTab] = useState<'stats' | 'payments' | 'config'>('stats');
  const totalVolume = transactions.reduce((a, b) => a + Math.abs(b.amount), 0);
  const activeUsers = users.filter(u => u.isActivated).length;

  const handleQRUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdateConfig({ ...config, qrCode: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex gap-2 bg-white p-1 rounded-xl shadow-sm border w-fit">
        {['stats', 'payments', 'config'].map(t => (
          <button 
            key={t} onClick={() => setActiveTab(t as any)}
            className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === t ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            {t.toUpperCase()}
          </button>
        ))}
      </div>

      {activeTab === 'stats' && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {[
            { l: 'Platform Revenue', v: `₹${(totalVolume * 0.05).toFixed(2)}`, c: 'text-emerald-600' },
            { l: 'System Volume', v: `₹${totalVolume.toFixed(2)}`, c: 'text-indigo-600' },
            { l: 'Total Active Users', v: activeUsers.toString(), c: 'text-slate-900' },
            { l: 'Package Price', v: `₹${config.packagePrice}`, c: 'text-orange-500' },
          ].map(s => (
            <div key={s.l} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{s.l}</p>
              <p className={`text-2xl font-black mt-1 ${s.c}`}>{s.v}</p>
            </div>
          ))}
        </div>
      )}

      {activeTab === 'payments' && (
        <div className="bg-white rounded-2xl border shadow-sm overflow-hidden">
          <div className="p-4 border-b bg-slate-50">
             <h3 className="font-bold text-slate-800">Pending Add Money Requests</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-slate-400 font-bold text-[10px] uppercase">
                <tr>
                  <th className="px-6 py-3">User</th>
                  <th className="px-6 py-3">Amount</th>
                  <th className="px-6 py-3">UTR</th>
                  <th className="px-6 py-3">Screenshot</th>
                  <th className="px-6 py-3">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {paymentRequests.filter(r => r.status === 'pending').map(req => (
                  <tr key={req.id}>
                    <td className="px-6 py-4 font-bold">{req.userName}</td>
                    <td className="px-6 py-4 text-emerald-600 font-black">₹{req.amount}</td>
                    <td className="px-6 py-4 font-mono text-xs">{req.utr}</td>
                    <td className="px-6 py-4">
                      <a href={req.screenshot} target="_blank" rel="noreferrer" className="text-indigo-600 font-bold hover:underline">View File</a>
                    </td>
                    <td className="px-6 py-4">
                      <button 
                        onClick={() => onApprovePayment(req.id)}
                        className="bg-emerald-500 text-white px-3 py-1 rounded-lg text-xs font-bold hover:bg-emerald-600 transition-colors"
                      >
                        APPROVE
                      </button>
                    </td>
                  </tr>
                ))}
                {paymentRequests.filter(r => r.status === 'pending').length === 0 && (
                  <tr><td colSpan={5} className="px-6 py-12 text-center text-slate-400">No pending requests</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'config' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-2xl border shadow-sm">
            <h3 className="font-black text-slate-800 mb-6 flex items-center gap-2">
              <span className="w-2 h-6 bg-indigo-600 rounded-full"></span>
              QR Code Setup
            </h3>
            <div className="space-y-4">
              <div className="aspect-square bg-slate-100 rounded-2xl flex items-center justify-center border-2 border-dashed border-slate-300 relative overflow-hidden">
                {config.qrCode ? (
                  <img src={config.qrCode} alt="Admin QR" className="w-full h-full object-contain" />
                ) : (
                  <span className="text-slate-400 text-xs font-bold">No QR Uploaded</span>
                )}
              </div>
              <input 
                type="file" 
                accept="image/*"
                onChange={handleQRUpload}
                className="hidden" id="qr-input"
              />
              <label 
                htmlFor="qr-input"
                className="block text-center w-full py-3 bg-indigo-600 text-white font-bold rounded-xl cursor-pointer hover:bg-indigo-700 transition-colors"
              >
                {config.qrCode ? 'Update QR Code' : 'Upload QR Code'}
              </label>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-6 rounded-2xl border shadow-sm">
              <h3 className="font-black text-slate-800 mb-6">Package Commissions (Level 1-10)</h3>
              <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
                {config.packageCommission.map((val, i) => (
                  <div key={i}>
                    <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">L{i+1}</label>
                    <input 
                      type="number"
                      value={val}
                      onChange={(e) => {
                        const newComs = [...config.packageCommission];
                        newComs[i] = parseFloat(e.target.value);
                        onUpdateConfig({ ...config, packageCommission: newComs });
                      }}
                      className="w-full px-2 py-1.5 bg-slate-50 border rounded text-xs font-bold"
                    />
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-white p-6 rounded-2xl border shadow-sm">
               <h3 className="font-black text-slate-800 mb-4 text-sm">Base Settings</h3>
               <div className="grid grid-cols-3 gap-4">
                 <div>
                   <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Price</label>
                   <input type="number" value={config.packagePrice} onChange={e => onUpdateConfig({...config, packagePrice: parseFloat(e.target.value)})} className="w-full px-3 py-2 bg-slate-50 border rounded text-xs font-bold" />
                 </div>
                 <div>
                   <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">TDS %</label>
                   <input type="number" step="0.01" value={config.tdsRate} onChange={e => onUpdateConfig({...config, tdsRate: parseFloat(e.target.value)})} className="w-full px-3 py-2 bg-slate-50 border rounded text-xs font-bold" />
                 </div>
                 <div>
                   <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Service %</label>
                   <input type="number" step="0.01" value={config.serviceCharge} onChange={e => onUpdateConfig({...config, serviceCharge: parseFloat(e.target.value)})} className="w-full px-3 py-2 bg-slate-50 border rounded text-xs font-bold" />
                 </div>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useMemo } from 'react';
import { User, Transaction, Product, PaymentRequest } from '../types';

interface DashboardProps {
  user: User;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  onRecharge: (userId: string, amt: number, service: string) => void;
  onOrder: (userId: string, pId: string) => void;
  onTransfer: (senderId: string, recipientEmail: string, amount: number) => void;
  onActivate: (userId: string) => void;
  packagePrice: number;
  qrCode: string;
  onAddMoney: (data: { amount: number, utr: string, screenshot: string }) => void;
  paymentRequests: PaymentRequest[];
}

const Dashboard: React.FC<DashboardProps> = ({ 
  user, users, products, transactions, onRecharge, onOrder, onTransfer, 
  onActivate, packagePrice, qrCode, onAddMoney, paymentRequests 
}) => {
  const [tab, setTab] = useState<'home' | 'utility' | 'shop' | 'transfer' | 'mlm' | 'add_money'>('home');
  const [transferData, setTransferData] = useState({ email: '', amount: '' });
  const [addMoneyData, setAddMoneyData] = useState({ amount: '', utr: '', screenshot: '' });

  const todayDateString = new Date().toISOString().split('T')[0];
  const todayIncome = useMemo(() => transactions.filter(tx => tx.createdAt.startsWith(todayDateString) && tx.amount > 0 && (tx.walletType === 'commission' || tx.walletType === 'cashback')).reduce((sum, tx) => sum + tx.amount, 0), [transactions, todayDateString]);

  const myDownline = useMemo(() => {
    const findDownline = (uId: string): User[] => {
      const directs = users.filter(u => u.referrerId === uId);
      let fullList = [...directs];
      directs.forEach(d => fullList = [...fullList, ...findDownline(d.id)]);
      return fullList;
    };
    return findDownline(user.id);
  }, [users, user.id]);

  const stats = [
    { label: 'Recharge Wallet', val: `₹${user.wallets.recharge.toFixed(2)}`, color: 'text-indigo-600' },
    { label: 'Main Wallet', val: `₹${user.wallets.main.toFixed(2)}`, color: 'text-slate-900' },
    { label: 'Today Income', val: `₹${todayIncome.toFixed(2)}`, color: 'text-emerald-600' },
    { label: 'Total Earnings', val: `₹${user.totalEarned.toFixed(2)}`, color: 'text-blue-600' },
    { label: 'Team Size', val: myDownline.length.toString(), color: 'text-orange-600' },
  ];

  const handleScreenshotChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setAddMoneyData({ ...addMoneyData, screenshot: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleAddMoneySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const amt = parseFloat(addMoneyData.amount);
    if (isNaN(amt) || amt <= 0) return alert('Enter valid amount');
    if (!addMoneyData.utr) return alert('Enter UTR Number');
    if (!addMoneyData.screenshot) return alert('Upload payment screenshot');
    onAddMoney({ amount: amt, utr: addMoneyData.utr, screenshot: addMoneyData.screenshot });
    setAddMoneyData({ amount: '', utr: '', screenshot: '' });
  };

  return (
    <div className="space-y-6">
      {!user.isActivated && (
        <div className="bg-red-50 border border-red-200 p-6 rounded-2xl flex flex-col md:flex-row items-center justify-between gap-4">
           <div>
              <h3 className="text-red-800 font-bold text-lg">Account Inactive</h3>
              <p className="text-red-600 text-sm">Purchase Activation Package for ₹{packagePrice}. Add money to Recharge wallet first.</p>
           </div>
           <button onClick={() => onActivate(user.id)} className="bg-red-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg">Activate Now</button>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {stats.map(s => (
          <div key={s.label} className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{s.label}</p>
            <p className={`text-xl font-black mt-1 ${s.color}`}>{s.val}</p>
          </div>
        ))}
      </div>

      <nav className="flex gap-1 bg-white p-1 rounded-xl shadow-sm border w-fit overflow-x-auto max-w-full">
        {['home', 'add_money', 'utility', 'shop', 'transfer', 'mlm'].map(t => (
          <button 
            key={t} onClick={() => setTab(t as any)}
            className={`px-5 py-2.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${tab === t ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            {t.replace('_', ' ').toUpperCase()}
          </button>
        ))}
      </nav>

      {tab === 'home' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
            <h3 className="text-lg font-bold mb-4">Transaction Logs</h3>
            <div className="space-y-3">
              {transactions.slice(0, 8).map(tx => (
                <div key={tx.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${tx.amount > 0 ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                      {tx.type[0].toUpperCase()}
                    </div>
                    <div>
                      <p className="text-xs font-bold text-slate-800">{tx.description}</p>
                      <p className="text-[9px] text-slate-400">{new Date(tx.createdAt).toLocaleString()}</p>
                    </div>
                  </div>
                  <p className={`text-sm font-black ${tx.amount > 0 ? 'text-emerald-600' : 'text-rose-600'}`}>₹{tx.amount.toFixed(2)}</p>
                </div>
              ))}
              {transactions.length === 0 && <p className="text-center py-10 text-slate-400 text-xs">No transactions yet.</p>}
            </div>
          </div>
          <div className="space-y-6">
            <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-6 rounded-2xl text-white shadow-lg">
              <h4 className="font-bold mb-1">Referral Link</h4>
              <p className="text-[10px] text-indigo-100 mb-4">Earn from 10 levels of active downline.</p>
              <div className="bg-white/10 p-3 rounded-lg flex justify-between items-center border border-white/20">
                <span className="font-mono font-bold text-sm">{user.referralCode}</span>
                <button onClick={() => {navigator.clipboard.writeText(user.referralCode); alert('Copied!');}} className="text-[10px] font-bold px-3 py-1 bg-white text-indigo-600 rounded">COPY</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {tab === 'add_money' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-5xl mx-auto">
          <div className="bg-white p-8 rounded-3xl border shadow-sm text-center flex flex-col items-center">
            <h3 className="text-lg font-black mb-6 text-slate-800">Scan & Pay to Add Money</h3>
            {qrCode ? (
              <div className="p-4 bg-white border-4 border-slate-50 rounded-3xl shadow-inner mb-6">
                 <img src={qrCode} alt="Payment QR" className="w-64 h-64 object-contain" />
              </div>
            ) : (
              <div className="w-64 h-64 bg-slate-100 rounded-3xl flex items-center justify-center text-slate-400 text-xs font-bold border-2 border-dashed mb-6">
                 Admin hasn't uploaded QR code yet.
              </div>
            )}
            <p className="text-xs text-slate-500 leading-relaxed font-medium">
              1. Scan the QR code above.<br/>
              2. Make payment via any UPI App.<br/>
              3. Enter UTR and Amount below.<br/>
              4. Upload Screenshot and Submit.
            </p>
          </div>

          <div className="bg-white p-8 rounded-3xl border shadow-sm">
            <h3 className="text-lg font-black mb-6 text-slate-800">Payment Proof Details</h3>
            <form onSubmit={handleAddMoneySubmit} className="space-y-5">
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Deposit Amount (₹)</label>
                <input 
                  type="number" required placeholder="0.00"
                  className="w-full px-5 py-3 bg-slate-50 border rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:outline-none font-bold"
                  value={addMoneyData.amount} onChange={e => setAddMoneyData({...addMoneyData, amount: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">UTR / Transaction ID</label>
                <input 
                  type="text" required placeholder="12-digit UPI Transaction ID"
                  className="w-full px-5 py-3 bg-slate-50 border rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:outline-none font-mono text-sm"
                  value={addMoneyData.utr} onChange={e => setAddMoneyData({...addMoneyData, utr: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Upload Screenshot</label>
                <input 
                  type="file" accept="image/*" required
                  className="w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-bold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100"
                  onChange={handleScreenshotChange}
                />
              </div>
              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-[0.98] transition-all">
                SUBMIT FOR APPROVAL
              </button>
            </form>

            <div className="mt-8 border-t pt-6">
              <h4 className="text-[10px] font-bold text-slate-400 uppercase mb-4 tracking-wider">Recent Requests</h4>
              <div className="space-y-2 max-h-48 overflow-y-auto pr-2">
                {paymentRequests.map(r => (
                  <div key={r.id} className="p-3 bg-slate-50 rounded-xl border flex justify-between items-center text-[10px]">
                    <div>
                      <p className="font-bold text-slate-700">₹{r.amount} - UTR: {r.utr}</p>
                      <p className="text-slate-400">{new Date(r.createdAt).toLocaleDateString()}</p>
                    </div>
                    <span className={`px-2 py-0.5 rounded-full font-black uppercase text-[8px] ${
                      r.status === 'approved' ? 'bg-emerald-100 text-emerald-600' : 
                      r.status === 'pending' ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'
                    }`}>
                      {r.status}
                    </span>
                  </div>
                ))}
                {paymentRequests.length === 0 && <p className="text-center text-slate-300 text-[10px] py-4 italic">No previous requests found.</p>}
              </div>
            </div>
          </div>
        </div>
      )}

      {tab === 'utility' && (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
          {[
            { name: 'Mobile', icon: '📱', color: 'bg-blue-100' },
            { name: 'DTH', icon: '📡', color: 'bg-purple-100' },
            { name: 'Electricity', icon: '⚡', color: 'bg-yellow-100' },
            { name: 'Water', icon: '💧', color: 'bg-cyan-100' },
            { name: 'FASTag', icon: '🚗', color: 'bg-green-100' },
            { name: 'Broadband', icon: '🌐', color: 'bg-indigo-100' },
          ].map(s => (
            <button 
              key={s.name} disabled={!user.isActivated}
              onClick={() => { const amt = prompt(`Enter ${s.name} amount:`); if(amt) onRecharge(user.id, parseFloat(amt), s.name); }}
              className={`bg-white p-6 rounded-2xl border transition-all group shadow-sm text-center ${!user.isActivated ? 'opacity-50 grayscale' : 'hover:border-indigo-300'}`}
            >
              <div className={`w-12 h-12 ${s.color} rounded-2xl flex items-center justify-center mx-auto mb-3 text-2xl`}>{s.icon}</div>
              <p className="text-xs font-bold text-slate-700">{s.name}</p>
            </button>
          ))}
        </div>
      )}

      {tab === 'transfer' && (
        <div className="max-w-md mx-auto bg-white p-8 rounded-3xl border shadow-sm">
          <h3 className="text-lg font-black mb-6 text-slate-800">User Fund Transfer</h3>
          <form onSubmit={(e) => {
            e.preventDefault();
            const amt = parseFloat(transferData.amount);
            if(isNaN(amt) || amt <= 0) return alert('Invalid amount');
            onTransfer(user.id, transferData.email, amt);
            setTransferData({ email: '', amount: '' });
          }} className="space-y-5">
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5 ml-1">Recipient Email</label>
              <input type="email" required placeholder="user@spay360.com" className="w-full px-5 py-3 bg-slate-50 border rounded-2xl focus:outline-none" value={transferData.email} onChange={e => setTransferData({...transferData, email: e.target.value})} />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1.5 ml-1">Amount (₹)</label>
              <input type="number" required placeholder="0.00" className="w-full px-5 py-3 bg-slate-50 border rounded-2xl focus:outline-none" value={transferData.amount} onChange={e => setTransferData({...transferData, amount: e.target.value})} />
            </div>
            <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl">TRANSFER NOW</button>
          </form>
        </div>
      )}

      {tab === 'shop' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {products.map(p => (
            <div key={p.id} className="bg-white rounded-2xl border overflow-hidden shadow-sm group">
              <div className="h-40 bg-slate-50 flex items-center justify-center text-4xl">{p.image}</div>
              <div className="p-4">
                <h4 className="font-bold text-sm text-slate-800">{p.name}</h4>
                <div className="flex items-center justify-between mt-4">
                  <span className="text-md font-black">₹{p.price}</span>
                  <button onClick={() => onOrder(user.id, p.id)} className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-bold rounded-lg">BUY</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {tab === 'mlm' && (
        <div className="bg-white p-6 rounded-2xl shadow-sm border">
          <h3 className="text-lg font-bold mb-6">Downline Tree (10 Levels)</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[...Array(10)].map((_, i) => {
              const levelMembers = myDownline.filter(u => u.level === (user.level + i + 1));
              return (
                <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border">
                  <span className="font-black text-slate-400 text-xs">Level {i+1}</span>
                  <div className="text-right">
                    <p className="font-bold text-sm">{levelMembers.length} Members</p>
                    <p className="text-[10px] text-emerald-600 font-bold">{levelMembers.filter(u => u.isActivated).length} Active</p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';

interface AuthProps {
  onLogin: (email: string, password?: string) => void;
  onSignup: (data: any) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin, onSignup }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phone: '',
