import React, { useState, useMemo } from 'react';
import { User, Transaction, Product, PaymentRequest } from '../types';

interface DashboardProps {
  user: User;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  onRecharge: (userId: string, amt: number, service: string) => void;
  onOrder: (userId: string, pId: string) => void;
  onTransfer: (senderId: string, recipientEmail: string, amount: number) => void;
  onActivate: (userId: string) => void;
  packagePrice: number;
  qrCode: string;
  onAddMoney: (data: { amount: number, utr: string, screenshot: string }) => void;
  paymentRequests: PaymentRequest[];
}

const Dashboard: React.FC<DashboardProps> = ({ 
  user, users, products, transactions, onRecharge, onOrder, onTransfer, 
  onActivate, packagePrice, qrCode, onAddMoney, paymentRequests 
}) => {
  const [tab, setTab] = useState<'home' | 'utility' | 'shop' | 'transfer' | 'mlm' | 'add_money'>('home');
  const [transferData, setTransferData] = useState({ email: '', amount: '' });
  const [addMoneyData, setAddMoneyData] = useState({ amount: '', utr: '', screenshot: '' });

  const todayDateString = new Date().toISOString().split('T')[0];
  const todayIncome = useMemo(() => transactions.filter(tx => tx.createdAt.startsWith(todayDateString) && tx.amount > 0 && (tx.walletType === 'commission' || tx.walletType === 'cashback')).reduce((sum, tx) => sum + tx.amount, 0), [transactions, todayDateString]);

  const myDownline = useMemo(() => {
    const findDownline = (uId: string): User[] => {
      const directs = users.filter(u => u.referrerId === uId);
      let fullList = [...directs];
      directs.forEach(d => fullList = [...fullList, ...findDownline(d.id)]);
      return fullList;
    };
    return findDownline(user.id);
  }, [users, user.id]);

  const stats = [
    { label: 'Recharge Wallet', val: `₹${user.wallets.recharge.toFixed(2)}`, color: 'text-red-600' },
    { label: 'Main Wallet', val: `₹${user.wallets.main.toFixed(2)}`, color: 'text-slate-900' },
    { label: 'Today Income', val: `₹${todayIncome.toFixed(2)}`, color: 'text-emerald-600' },
    { label: 'Total Earnings', val: `₹${user.totalEarned.toFixed(2)}`, color: 'text-blue-600' },
    { label: 'Team Size', val: myDownline.length.toString(), color: 'text-orange-600' },
  ];

  const handleScreenshotChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setAddMoneyData({ ...addMoneyData, screenshot: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleAddMoneySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const amt = parseFloat(addMoneyData.amount);
    if (isNaN(amt) || amt <= 0) return alert('Enter valid amount');
    if (!addMoneyData.utr) return alert('Enter UTR Number');
    if (!addMoneyData.screenshot) return alert('Upload payment screenshot');
    onAddMoney({ amount: amt, utr: addMoneyData.utr, screenshot: addMoneyData.screenshot });
    setAddMoneyData({ amount: '', utr: '', screenshot: '' });
  };

  return (
    <div className="space-y-6">
      {!user.isActivated && (
        <div className="bg-red-50 border border-red-200 p-6 rounded-2xl flex flex-col md:flex-row items-center justify-between gap-4">
           <div>
              <h3 className="text-red-800 font-bold text-lg">Account Inactive</h3>
              <p className="text-red-600 text-sm">Purchase Activation Package for ₹{packagePrice}. Add money to Recharge wallet first.</p>
           </div>
           <button onClick={() => onActivate(user.id)} className="bg-red-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg">Activate Now</button>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {stats.map(s => (
          <div key={s.label} className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{s.label}</p>
            <p className={`text-xl font-black mt-1 ${s.color}`}>{s.val}</p>
          </div>
        ))}
      </div>

      <nav className="flex gap-1 bg-white p-1 rounded-xl shadow-sm border w-fit overflow-x-auto max-w-full">
        {['home', 'add_money', 'utility', 'shop', 'transfer', 'mlm'].map(t => (
          <button 
            key={t} onClick={() => setTab(t as any)}
            className={`px-5 py-2.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${tab === t ? 'bg-red-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            {t.replace('_', ' ').toUpperCase()}
          </button>
        ))}
      </nav>

      {tab === 'home' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
            <h3 className="text-lg font-bold mb-4">Transaction Logs</h3>
            <div className="space-y-3">
              {transactions.slice(0, 8).map(tx => (
                <div key={tx.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${tx.amount > 0 ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                      {tx.type[0].toUpperCase()}
                    </div>
                    <div>
                      <p className="text-xs font-bold text-slate-800">{tx.description}</p>
                      <p className="text-[9px] text-slate-400">{new Date(tx.createdAt).toLocaleString()}</p>
                    </div>
                  </div>
                  <p className={`text-sm font-black ${tx.amount > 0 ? 'text-emerald-600' : 'text-rose-600'}`}>₹{tx.amount.toFixed(2)}</p>
                </div>
              ))}
              {transactions.length === 0 && <p className="text-center py-10 text-slate-400 text-xs">No transactions yet.</p>}
            </div>
          </div>
          <div className="space-y-6">
            <div className="bg-gradient-to-br from-red-600 to-orange-600 p-6 rounded-2xl text-white shadow-lg">
              <h4 className="font-bold mb-1">Referral Link</h4>
              <p className="text-[10px] text-red-100 mb-4">Earn from 10 levels of active downline.</p>
              <div className="bg-white/10 p-3 rounded-lg flex justify-between items-center border border-white/20">
                <span className="font-mono font-bold text-sm">{user.referralCode}</span>
                <button onClick={() => {navigator.clipboard.writeText(user.referralCode); alert('Copied!');}} className="text-[10px] font-bold px-3 py-1 bg-white text-red-600 rounded">COPY</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {tab === 'add_money' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-5xl mx-auto">
          <div className="bg-white p-8 rounded-3xl border shadow-sm text-center flex flex-col items-center">
            <h3 className="text-lg font-black mb-6 text-slate-800">Scan & Pay to Add Money</h3>
            {qrCode ? (
              <div className="p-4 bg-white border-4 border-slate-50 rounded-3xl shadow-inner mb-6">
                 <img src={qrCode} alt="Payment QR" className="w-64 h-64 object-contain" />
              </div>
            ) : (
              <div className="w-64 h-64 bg-slate-100 rounded-3xl flex items-center justify-center text-slate-400 text-xs font-bold border-2 border-dashed mb-6">
                 Admin hasn't uploaded QR code yet.
              </div>
            )}
            <p className="text-xs text-slate-500 leading-relaxed font-medium">
              1. Scan the QR code above.<br/>
              2. Make payment via any UPI App.<br/>
              3. Enter UTR and Amount below.<br/>
              4. Upload Screenshot and Submit.
            </p>
          </div>

          <div className="bg-white p-8 rounded-3xl border shadow-sm">
            <h3 className="text-lg font-black mb-6 text-slate-800">Payment Proof Details</h3>
            <form onSubmit={handleAddMoneySubmit} className="space-y-5">
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Deposit Amount (₹)</label>
                <input 
                  type="number" required placeholder="0.00"
                  className="w-full px-5 py-3 bg-slate-50 border rounded-2xl focus:ring-4 focus:ring-red-500/10 focus:outline-none font-bold"
                  value={addMoneyData.amount} onChange={e => setAddMoneyData({...addMoneyData, amount: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">UTR / Transaction ID</label>
                <input 
                  type="text" required placeholder="12-digit UPI Transaction ID"
                  className="w-full px-5 py-3 bg-slate-50 border rounded-2xl focus:ring-4 focus:ring-red-500/10 focus:outline-none font-mono text-sm"
                  value={addMoneyData.utr} onChange={e => setAddMoneyData({...addMoneyData, utr: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Upload Screenshot</label>
                <input 
                  type="file" accept="image/*" required
                  className="w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-bold file:bg-red-50 file:text-red-700 hover:file:bg-red-100"
                  onChange={handleScreenshotChange}
                />
              </div>
              <button type="submit" className="w-full py-4 bg-red-600 text-white font-black rounded-2xl shadow-xl hover:bg-red-700 active:scale-[0.98] transition-all">
                SUBMIT FOR APPROVAL
              </button>
            </form>

            <div className="mt-8 border-t pt-6">
              <h4 className="text-[10px] font-bold text-slate-400 uppercase mb-4 tracking-wider">Recent Requests</h4>
              <div className="space-y-2 max-h-48 overflow-y-auto pr-2">
                {paymentRequests.map(r => (
                  <div key={r.id} className="p-3 bg-slate-50 rounded-xl border flex justify-between items-center text-[10px]">
                    <div>
                      <p className="font-bold text-slate-700">₹{r.amount} - UTR: {r.utr}</p>
                      <p className="text-slate-400">{new Date(r.createdAt).toLocaleDateString()}</p>
                    </div>
                    <span className={`px-2 py-0.5 rounded-full font-black uppercase text-[8px] ${
                      r.status === 'approved' ? 'bg-emerald-100 text-emerald-600' : 
                      r.status === 'pending' ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'
                    }`}>
                      {r.status}
                    </span>
                  </div>
                ))}
                {paymentRequests.length === 0 && <p className="text-center text-slate-300 text-[10px] py-4 italic">No previous requests found.</p>}
              </div>
            </div>
          </div>
        </div>
      )}

      {tab === 'utility' && (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
          {[
            { name: 'Mobile', icon: '📱', color: 'bg-red-100' },
            { name: 'DTH', icon: '📡', color: 'bg-orange-100' },
            { name: 'Electricity', icon: '⚡', color: 'bg-yellow-100' },
            { name: 'Water', icon: '💧', color: 'bg-blue-100' },
            { name: 'FASTag', icon: '🚗', color: 'bg-emerald-100' },
            { name: 'Broadband', icon: '🌐', color: 'bg-indigo-100' },
          ].map(s => (
            <button 
              key={s.name} disabled={!user.isActivated}
              onClick={() => { const amt = prompt(`Enter ${s.name} amount:`); if(amt) onRecharge(user.id, parseFloat(amt), s.name); }}
              className={`bg-white p-6 rounded-2xl border transition-all group shadow-sm text-center ${!user.isActivated ? 'opacity-50 grayscale' : 'hover:border-red-300'}`}
            >
              <div className={`w-12 h-12 ${s.color} rounded-2xl flex items-center justify-center mx-auto mb-3 text-2xl`}>{s.icon}</div>
