import React, { useState } from 'react';
import { User, Transaction, MLMConfig, UserRole, PaymentRequest } from '../types';

interface AdminProps {
  users: User[];
  transactions: Transaction[];
  config: MLMConfig;
  onUpdateConfig: (c: MLMConfig) => void;
  paymentRequests: PaymentRequest[];
  onApprovePayment: (id: string) => void;
}

const AdminPanel: React.FC<AdminProps> = ({ users, transactions, config, onUpdateConfig, paymentRequests, onApprovePayment }) => {
  const [activeTab, setActiveTab] = useState<'stats' | 'payments' | 'config'>('stats');
  const totalVolume = transactions.reduce((a, b) => a + Math.abs(b.amount), 0);
  const activeUsers = users.filter(u => u.isActivated).length;

  const handleQRUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdateConfig({ ...config, qrCode: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

