              {[50, 100, 200, 500, 1000].map(amt => (
                <button key={amt} onClick={() => setWithdrawalAmount(amt.toString())} className="py-2 bg-red-50 text-red-600 text-xs font-black border border-red-100 rounded-lg hover:bg-red-600 hover:text-white transition-all">
                  ₹{amt}
                </button>
              ))}
            </div>

            <form onSubmit={handleWithdrawalSubmit} className="space-y-4">
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1 ml-1">Amount to Withdraw (₹)</label>
                <input type="number" min="50" className="w-full px-5 py-3 bg-slate-50 border rounded-2xl focus:ring-4 focus:ring-red-500/10 focus:outline-none font-bold" value={withdrawalAmount} onChange={e => setWithdrawalAmount(e.target.value)} required />
