        wallets: { main: 1000000, commission: 0, cashback: 0, recharge: 1000000 },
        totalEarned: 0,
        status: 'active',
        level: 0,
        joinedAt: new Date().toISOString(),
        isActivated: true
      };
      setUsers(prev => [admin, ...prev.filter(u => u.email.toLowerCase() !== adminEmail)]);
    }
