      )}

      {tab === 'utility' && (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
          {[
            { name: 'Mobile', icon: '📱', color: 'bg-blue-100' },
            { name: 'DTH', icon: '📡', color: 'bg-orange-100' },
            { name: 'Electricity', icon: '⚡', color: 'bg-yellow-100' },
            { name: 'Water', icon: '💧', color: 'bg-cyan-100' },
            { name: 'FASTag', icon: '🚗', color: 'bg-emerald-100' },
            { name: 'Broadband', icon: '🌐', color: 'bg-indigo-100' },
          ].map(s => (
            <button key={s.name} disabled={!user.isActivated} onClick={() => initiateRecharge(s.name)}
              className={`bg-white p-6 rounded-2xl border shadow-sm text-center ${!user.isActivated ? 'opacity-50 grayscale' : 'hover:border-blue-300'}`}>
              <div className={`w-12 h-12 ${s.color} rounded-2xl flex items-center justify-center mx-auto mb-3 text-2xl`}>{s.icon}</div>
              <p className="text-xs font-bold text-slate-700">{s.name}</p>
            </button>
          ))}
        </div>
      )}

      {/* ... Rest of tabs (mlm, support, add_money, shop) omitted for brevity as they haven't changed Pin logic ... */}
      {tab === 'mlm' && (
        <div className="bg-white p-6 rounded-2xl shadow-sm border">
          <h3 className="text-lg font-bold mb-6">Downline Tree (10 Levels)</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {[...Array(10)].map((_, i) => {
              const levelMembers = myDownline.filter(u => u.level === (user.level + i + 1));
              return (
                <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border">
                  <span className="font-black text-slate-400 text-xs">Level {i+1}</span>
                  <div className="text-right">
                    <p className="font-bold text-sm">{levelMembers.length} Members</p>
                    <p className="text-[10px] text-green-600 font-bold">{levelMembers.filter(u => u.isActivated).length} Active</p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

export enum UserRole {
  ADMIN = 'ADMIN',
  USER = 'USER',
  VENDOR = 'VENDOR'
}

export interface Wallets {
  main: number;
  commission: number;
  cashback: number;
  recharge: number;
  vendor?: number;
}

export interface BankDetails {
  accountNumber: string;
  bankName: string;
  ifscCode: string;
  holderName: string;
}

export interface WithdrawalRequest {
  id: string;
  userId: string;
  userName: string;
  amount: number;
  status: 'pending' | 'approved' | 'rejected';
  createdAt: string;
  bankDetails: BankDetails;
}

export interface ChatMessage {
  id: string;
  senderId: string;
  senderName: string;
  receiverId: string; // 'admin' or userId
  message: string;
  createdAt: string;
}

export interface PaymentRequest {
  id: string;
  userId: string;
  userName: string;
  amount: number;
  utr: string;
  screenshot: string; // Base64
  status: 'pending' | 'approved' | 'rejected';
  createdAt: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  transactionPin: string; // 4-digit PIN for sensitive actions
  phone: string;
  state: string; // User's state location
  referralCode: string;
  referrerId: string | null;
  role: UserRole;
  wallets: Wallets;
  totalEarned: number;
  status: 'active' | 'suspended' | 'pending';
  level: number;
  joinedAt: string;
  isActivated: boolean;
  bankDetails?: BankDetails;
  kycData?: {
    pan: string;
    aadhaar: string;
  };
}

export interface Product {
  id: string;
  vendorId: string;
  name: string;
  description: string;
  price: number;
  mrp: number;
  category: 'Herbal' | 'Electronics' | 'Wellness' | 'Utility';
  stock: number;
  image: string;
  mlmPoints: number;
}

export interface Order {
  id: string;
  userId: string;
  vendorId: string;
  productId: string;
  amount: number;
  status: 'pending' | 'shipped' | 'delivered' | 'cancelled';
  createdAt: string;
}

export interface Transaction {
  id: string;
  userId: string;
  amount: number;
  walletType: keyof Wallets;
  type: 'recharge' | 'commission' | 'shopping' | 'withdrawal' | 'add_funds' | 'activation';
  description: string;
  status: 'success' | 'pending' | 'failed';
  createdAt: string;
}

export interface MLMConfig {
  rechargeCommission: number[];
  productCommission: number[];
  packageCommission: number[];
  packagePrice: number;
  tdsRate: number;
  serviceCharge: number;
  qrCode: string; // Admin QR for Add Money
}

