import React, { useState, useEffect } from 'react';
import { User, UserRole, Transaction, Product, Order, MLMConfig, Wallets, PaymentRequest, WithdrawalRequest, ChatMessage } from './types';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import AdminPanel from './components/AdminPanel';
import VendorPanel from './components/VendorPanel';
import { Layout } from './components/Layout';

const DEFAULT_MLM_CONFIG: MLMConfig = {
  rechargeCommission: [0.05, 0.02, 0.01, 0.005, 0.005, 0.002, 0.002, 0.001, 0.001, 0.001],
  productCommission: [0.10, 0.05, 0.03, 0.02, 0.01, 0.01, 0.01, 0.005, 0.005, 0.005],
  packageCommission: [50, 20, 10, 5, 5, 2, 2, 1, 1, 1],
  packagePrice: 249,
  tdsRate: 0.05,
  serviceCharge: 0.05,
  qrCode: ''
};

const INITIAL_PRODUCTS: Product[] = [
  { id: 'p1', vendorId: 'v1', name: 'Premium Herbal Tea', description: 'Natural detox tea', price: 499, mrp: 699, category: 'Herbal', stock: 100, image: '☕', mlmPoints: 100 },
  { id: 'p2', vendorId: 'v1', name: 'Aloe Vera Gel', description: 'Pure organic aloe', price: 299, mrp: 399, category: 'Wellness', stock: 50, image: '🌿', mlmPoints: 50 },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(() => JSON.parse(localStorage.getItem('spay_users') || '[]'));
  const [products, setProducts] = useState<Product[]>(() => JSON.parse(localStorage.getItem('spay_products') || JSON.stringify(INITIAL_PRODUCTS)));
  const [orders, setOrders] = useState<Order[]>(() => JSON.parse(localStorage.getItem('spay_orders') || '[]'));
  const [transactions, setTransactions] = useState<Transaction[]>(() => JSON.parse(localStorage.getItem('spay_tx') || '[]'));
  const [mlmConfig, setMlmConfig] = useState<MLMConfig>(() => JSON.parse(localStorage.getItem('spay_config') || JSON.stringify(DEFAULT_MLM_CONFIG)));
  const [paymentRequests, setPaymentRequests] = useState<PaymentRequest[]>(() => JSON.parse(localStorage.getItem('spay_payments') || '[]'));
  const [withdrawalRequests, setWithdrawalRequests] = useState<WithdrawalRequest[]>(() => JSON.parse(localStorage.getItem('spay_withdrawals') || '[]'));
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>(() => JSON.parse(localStorage.getItem('spay_chats') || '[]'));

  useEffect(() => {
    const adminEmail = 'admin@spay.com';
    if (!users.some(u => u.email.toLowerCase() === adminEmail)) {
      const admin: User = {
        id: 'admin-0',
        name: 'System Admin',
        email: adminEmail,
        password: 'admin123',
        transactionPin: '1234',
        phone: '0000000000',
        state: 'Delhi',
        referralCode: 'SPAY001',
        referrerId: null,
        role: UserRole.ADMIN,
        wallets: { main: 1000000, commission: 0, cashback: 0, recharge: 1000000 },
        totalEarned: 0,
        status: 'active',
        level: 0,
        joinedAt: new Date().toISOString(),
        isActivated: true
      };
      setUsers(prev => [admin, ...prev.filter(u => u.email.toLowerCase() !== adminEmail)]);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('spay_users', JSON.stringify(users));
    localStorage.setItem('spay_products', JSON.stringify(products));
    localStorage.setItem('spay_orders', JSON.stringify(orders));
    localStorage.setItem('spay_tx', JSON.stringify(transactions));
    localStorage.setItem('spay_config', JSON.stringify(mlmConfig));
    localStorage.setItem('spay_payments', JSON.stringify(paymentRequests));
    localStorage.setItem('spay_withdrawals', JSON.stringify(withdrawalRequests));
    localStorage.setItem('spay_chats', JSON.stringify(chatMessages));
  }, [users, products, orders, transactions, mlmConfig, paymentRequests, withdrawalRequests, chatMessages]);

  const handleTransaction = (userId: string, amount: number, wallet: keyof Wallets, type: Transaction['type'], desc: string) => {
    setUsers(prev => prev.map(u => {
      if (u.id === userId) {
        const newWallets = { ...u.wallets, [wallet]: (u.wallets[wallet] || 0) + amount };
        return { ...u, wallets: newWallets, totalEarned: (amount > 0 && (wallet === 'commission' || wallet === 'cashback')) ? u.totalEarned + amount : u.totalEarned };
      }
      return u;
    }));
    setTransactions(prev => [{
      id: `TX${Date.now()}`, userId, amount, walletType: wallet, type, description: desc, status: 'success', createdAt: new Date().toISOString()
    }, ...prev]);
  };

  const handleSendMessage = (msg: string, receiverId: string) => {
    if (!currentUser) return;
    const newMessage: ChatMessage = {
      id: `MSG${Date.now()}`,
      senderId: currentUser.id,
      senderName: currentUser.name,
      receiverId,
      message: msg,
      createdAt: new Date().toISOString()
    };
    setChatMessages(prev => [...prev, newMessage]);
  };

  const handleWithdrawalRequest = (amount: number, pin: string) => {
    if (!currentUser) return;
    const user = users.find(u => u.id === currentUser.id);
    if (!user) return;
    if (user.transactionPin !== pin) return alert('Invalid Transaction PIN');
    if (!user.bankDetails) return alert('Please add bank details first');
    if (user.wallets.commission < amount) return alert('Insufficient commission balance');

    const newRequest: WithdrawalRequest = {
      id: `WITH${Date.now()}`,
      userId: user.id,
      userName: user.name,
      amount,
      status: 'pending',
      bankDetails: user.bankDetails,
      createdAt: new Date().toISOString()
    };

    handleTransaction(user.id, -amount, 'commission', 'withdrawal', `Withdrawal Request for ₹${amount}`);
    setWithdrawalRequests(prev => [newRequest, ...prev]);
    alert('Withdrawal request submitted successfully!');
  };

  const handleApproveWithdrawal = (id: string) => {
    setWithdrawalRequests(prev => prev.map(r => r.id === id ? { ...r, status: 'approved' } : r));
    alert('Withdrawal approved!');
  };

  const handleUpdateBankDetails = (details: any) => {
    if (!currentUser) return;
    setUsers(prev => prev.map(u => u.id === currentUser.id ? { ...u, bankDetails: details } : u));
    alert('Bank details updated!');
  };

  const handleAddMoneyRequest = (data: { amount: number, utr: string, screenshot: string }) => {
    if (!currentUser) return;
    const newRequest: PaymentRequest = {
      id: `PAY${Date.now()}`,
      userId: currentUser.id,
      userName: currentUser.name,
      amount: data.amount,
      utr: data.utr,
      screenshot: data.screenshot,
      status: 'pending',
      createdAt: new Date().toISOString()
    };
    setPaymentRequests(prev => [newRequest, ...prev]);
    alert('Request submitted! Funds will be added after admin verification.');
  };

  const handleApprovePayment = (requestId: string) => {
    const req = paymentRequests.find(r => r.id === requestId);
    if (!req || req.status !== 'pending') return;
    handleTransaction(req.userId, req.amount, 'recharge', 'add_funds', `Approved Add Money: UTR ${req.utr}`);
    setPaymentRequests(prev => prev.map(r => r.id === requestId ? { ...r, status: 'approved' } : r));
    alert('Payment Approved!');
  };

  const handleLogin = (email: string, password?: string) => {
    const trimmedEmail = email.trim().toLowerCase();
    const trimmedPassword = password?.trim();
    const u = users.find(user => 
      user.email.toLowerCase() === trimmedEmail && 
      user.password === trimmedPassword
    );
    if (u) setCurrentUser(u);
    else alert('Invalid credentials. Check email and password.');
  };

  const handleSignup = (data: any) => {
    if (users.some(u => u.email.toLowerCase() === data.email.toLowerCase().trim())) return alert('Email taken');
    const ref = users.find(u => u.referralCode === data.referralCode.trim()) || users[0];
    const newUser: User = {
      ...data, 
      email: data.email.trim(),
      password: data.password.trim(),
      transactionPin: data.transactionPin.trim(),
      state: data.state || 'Unknown',
      id: `U${Date.now()}`, role: UserRole.USER, 
      referralCode: `SP${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      referrerId: ref.id, level: ref.level + 1, wallets: { main: 0, commission: 0, cashback: 0, recharge: 0 },
      totalEarned: 0, status: 'pending', isActivated: false, joinedAt: new Date().toISOString()
    };
    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
  };

  const handleRecharge = (userId: string, amount: number, service: string, pin: string) => {
    const user = users.find(u => u.id === userId);
    if (!user || !user.isActivated) return alert('Please activate your account first.');
    if (user.transactionPin !== pin) return alert('Invalid Transaction PIN');
    if (user.wallets.recharge < amount) return alert('Insufficient Recharge Wallet balance');

    handleTransaction(userId, -amount, 'recharge', 'recharge', `${service} Payment`);
    const cashback = amount * 0.02;
    handleTransaction(userId, cashback, 'cashback', 'recharge', `Cashback for ${service}`);
    alert(`${service} recharge successful!`);
  };

  const placeOrder = (userId: string, productId: string) => {
    const user = users.find(u => u.id === userId);
    const product = products.find(p => p.id === productId);
    if (!user || !user.isActivated) return alert('Please activate your account first.');
    if (!product || user.wallets.main < product.price) return alert('Insufficient Main Wallet balance');

    handleTransaction(userId, -product.price, 'main', 'shopping', `Purchase: ${product.name}`);
    alert('Order placed successfully!');
  };

  const handleTransfer = (senderId: string, recipientEmail: string, amount: number, pin: string) => {
    const sender = users.find(u => u.id === senderId);
    if (!sender) return;
    if (sender.transactionPin !== pin) return alert('Invalid Transaction PIN');

    const recipient = users.find(u => u.email.toLowerCase() === recipientEmail.toLowerCase().trim());
    if (!recipient) return alert('Recipient not found');
    if (senderId === recipient.id) return alert('Cannot transfer to yourself');
    if (sender.wallets.main < amount) return alert('Insufficient balance');

    handleTransaction(senderId, -amount, 'main', 'withdrawal', `Transfer to ${recipient.name}`);
    handleTransaction(recipient.id, amount, 'main', 'add_funds', `Transfer from ${sender.name}`);
    alert('Transfer successful!');
  };

  const handleActivateAccount = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (!user) return;
    if (user.wallets.recharge < mlmConfig.packagePrice) return alert('Insufficient Recharge Wallet balance');

    handleTransaction(userId, -mlmConfig.packagePrice, 'recharge', 'activation', `Package Activation Fee`);
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, isActivated: true, status: 'active' } : u));
    alert('Account Activated Successfully!');
  };

  if (!currentUser) return <Auth onLogin={handleLogin} onSignup={handleSignup} />;

  const activeUser = users.find(u => u.id === currentUser.id) || currentUser;

  return (
    <Layout user={activeUser} onLogout={() => setCurrentUser(null)}>
      {activeUser.role === UserRole.ADMIN ? (
        <AdminPanel 
          users={users} 
          transactions={transactions} 
          config={mlmConfig} 
          onUpdateConfig={setMlmConfig}
          paymentRequests={paymentRequests}
          onApprovePayment={handleApprovePayment}
          withdrawalRequests={withdrawalRequests}
          onApproveWithdrawal={handleApproveWithdrawal}
          chatMessages={chatMessages}
          onSendMessage={handleSendMessage}
        />
      ) : (
        <Dashboard 
          user={activeUser} 
          users={users} 
          products={products}
          transactions={transactions.filter(t => t.userId === activeUser.id)} 
          onRecharge={handleRecharge}
          onOrder={placeOrder}
          onTransfer={handleTransfer}
          onActivate={handleActivateAccount}
          packagePrice={mlmConfig.packagePrice}
          qrCode={mlmConfig.qrCode}
          onAddMoney={handleAddMoneyRequest}
          paymentRequests={paymentRequests.filter(r => r.userId === activeUser.id)}
          withdrawalRequests={withdrawalRequests.filter(r => r.userId === activeUser.id)}
          onWithdrawal={handleWithdrawalRequest}
          onUpdateBankDetails={handleUpdateBankDetails}
          chatMessages={chatMessages.filter(m => m.senderId === activeUser.id || m.receiverId === activeUser.id)}
          onSendMessage={handleSendMessage}
        />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, UserRole, Transaction, Product, Order, MLMConfig, Wallets, PaymentRequest, WithdrawalRequest, ChatMessage } from './types';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import AdminPanel from './components/AdminPanel';
import VendorPanel from './components/VendorPanel';
import { Layout } from './components/Layout';

const DEFAULT_MLM_CONFIG: MLMConfig = {
  rechargeCommission: [0.05, 0.02, 0.01, 0.005, 0.005, 0.002, 0.002, 0.001, 0.001, 0.001],
  productCommission: [0.10, 0.05, 0.03, 0.02, 0.01, 0.01, 0.01, 0.005, 0.005, 0.005],
  packageCommission: [50, 20, 10, 5, 5, 2, 2, 1, 1, 1],
  packagePrice: 249,
  tdsRate: 0.05,
  serviceCharge: 0.05,
  qrCode: ''
};

const INITIAL_PRODUCTS: Product[] = [
  { id: 'p1', vendorId: 'v1', name: 'Premium Herbal Tea', description: 'Natural detox tea', price: 499, mrp: 699, category: 'Herbal', stock: 100, image: '☕', mlmPoints: 100 },
  { id: 'p2', vendorId: 'v1', name: 'Aloe Vera Gel', description: 'Pure organic aloe', price: 299, mrp: 399, category: 'Wellness', stock: 50, image: '🌿', mlmPoints: 50 },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(() => JSON.parse(localStorage.getItem('spay_users') || '[]'));
  const [products, setProducts] = useState<Product[]>(() => JSON.parse(localStorage.getItem('spay_products') || JSON.stringify(INITIAL_PRODUCTS)));
  const [orders, setOrders] = useState<Order[]>(() => JSON.parse(localStorage.getItem('spay_orders') || '[]'));
  const [transactions, setTransactions] = useState<Transaction[]>(() => JSON.parse(localStorage.getItem('spay_tx') || '[]'));
  const [mlmConfig, setMlmConfig] = useState<MLMConfig>(() => JSON.parse(localStorage.getItem('spay_config') || JSON.stringify(DEFAULT_MLM_CONFIG)));
  const [paymentRequests, setPaymentRequests] = useState<PaymentRequest[]>(() => JSON.parse(localStorage.getItem('spay_payments') || '[]'));
  const [withdrawalRequests, setWithdrawalRequests] = useState<WithdrawalRequest[]>(() => JSON.parse(localStorage.getItem('spay_withdrawals') || '[]'));
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>(() => JSON.parse(localStorage.getItem('spay_chats') || '[]'));

  useEffect(() => {
    const adminEmail = 'admin@spay.com';
    if (!users.some(u => u.email.toLowerCase() === adminEmail)) {
      const admin: User = {
        id: 'admin-0',
        name: 'System Admin',
        email: adminEmail,
        password: 'admin123',
        transactionPin: '1234',
        phone: '0000000000',
        state: 'Delhi',
        referralCode: 'SPAY001',
        referrerId: null,
        role: UserRole.ADMIN,
        wallets: { main: 1000000, commission: 0, cashback: 0, recharge: 1000000 },
        totalEarned: 0,
        status: 'active',
        level: 0,
        joinedAt: new Date().toISOString(),
        isActivated: true
      };
      setUsers(prev => [admin, ...prev.filter(u => u.email.toLowerCase() !== adminEmail)]);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('spay_users', JSON.stringify(users));
    localStorage.setItem('spay_products', JSON.stringify(products));
    localStorage.setItem('spay_orders', JSON.stringify(orders));
    localStorage.setItem('spay_tx', JSON.stringify(transactions));
    localStorage.setItem('spay_config', JSON.stringify(mlmConfig));
    localStorage.setItem('spay_payments', JSON.stringify(paymentRequests));
    localStorage.setItem('spay_withdrawals', JSON.stringify(withdrawalRequests));
    localStorage.setItem('spay_chats', JSON.stringify(chatMessages));
  }, [users, products, orders, transactions, mlmConfig, paymentRequests, withdrawalRequests, chatMessages]);

  const handleTransaction = (userId: string, amount: number, wallet: keyof Wallets, type: Transaction['type'], desc: string) => {
    setUsers(prev => prev.map(u => {
      if (u.id === userId) {
        const newWallets = { ...u.wallets, [wallet]: (u.wallets[wallet] || 0) + amount };
        return { ...u, wallets: newWallets, totalEarned: (amount > 0 && (wallet === 'commission' || wallet === 'cashback')) ? u.totalEarned + amount : u.totalEarned };
      }
      return u;
    }));
    setTransactions(prev => [{
      id: `TX${Date.now()}`, userId, amount, walletType: wallet, type, description: desc, status: 'success', createdAt: new Date().toISOString()
    }, ...prev]);
  };

  const handleSendMessage = (msg: string, receiverId: string) => {
    if (!currentUser) return;
    const newMessage: ChatMessage = {
      id: `MSG${Date.now()}`,
      senderId: currentUser.id,
      senderName: currentUser.name,
      receiverId,
      message: msg,
      createdAt: new Date().toISOString()
    };
    setChatMessages(prev => [...prev, newMessage]);
  };

  const handleWithdrawalRequest = (amount: number, pin: string) => {
    if (!currentUser) return;
    const user = users.find(u => u.id === currentUser.id);
    if (!user) return;
    if (user.transactionPin !== pin) return alert('Invalid Transaction PIN');
    if (!user.bankDetails) return alert('Please add bank details first');
    if (user.wallets.commission < amount) return alert('Insufficient commission balance');

    const newRequest: WithdrawalRequest = {
      id: `WITH${Date.now()}`,
      userId: user.id,
      userName: user.name,
      amount,
      status: 'pending',
      bankDetails: user.bankDetails,
      createdAt: new Date().toISOString()
    };

    handleTransaction(user.id, -amount, 'commission', 'withdrawal', `Withdrawal Request for ₹${amount}`);
    setWithdrawalRequests(prev => [newRequest, ...prev]);
    alert('Withdrawal request submitted successfully!');
  };

  const handleApproveWithdrawal = (id: string) => {
    setWithdrawalRequests(prev => prev.map(r => r.id === id ? { ...r, status: 'approved' } : r));
    alert('Withdrawal approved!');
  };

  const handleUpdateBankDetails = (details: any) => {
    if (!currentUser) return;
    setUsers(prev => prev.map(u => u.id === currentUser.id ? { ...u, bankDetails: details } : u));
    alert('Bank details updated!');
  };

  const handleAddMoneyRequest = (data: { amount: number, utr: string, screenshot: string }) => {
    if (!currentUser) return;
    const newRequest: PaymentRequest = {
      id: `PAY${Date.now()}`,
      userId: currentUser.id,
      userName: currentUser.name,
      amount: data.amount,
      utr: data.utr,
      screenshot: data.screenshot,
      status: 'pending',
      createdAt: new Date().toISOString()
    };
    setPaymentRequests(prev => [newRequest, ...prev]);
    alert('Request submitted! Funds will be added after admin verification.');
  };

  const handleApprovePayment = (requestId: string) => {
    const req = paymentRequests.find(r => r.id === requestId);
    if (!req || req.status !== 'pending') return;
    handleTransaction(req.userId, req.amount, 'recharge', 'add_funds', `Approved Add Money: UTR ${req.utr}`);
    setPaymentRequests(prev => prev.map(r => r.id === requestId ? { ...r, status: 'approved' } : r));
    alert('Payment Approved!');
  };

  const handleLogin = (email: string, password?: string) => {
    const trimmedEmail = email.trim().toLowerCase();
    const trimmedPassword = password?.trim();
    const u = users.find(user => 
      user.email.toLowerCase() === trimmedEmail && 
      user.password === trimmedPassword
    );
    if (u) setCurrentUser(u);
    else alert('Invalid credentials. Check email and password.');
  };

  const handleSignup = (data: any) => {
    if (users.some(u => u.email.toLowerCase() === data.email.toLowerCase().trim())) return alert('Email taken');
    const ref = users.find(u => u.referralCode === data.referralCode.trim()) || users[0];
    const newUser: User = {
      ...data, 
      email: data.email.trim(),
      password: data.password.trim(),
      transactionPin: data.transactionPin.trim(),
      state: data.state || 'Unknown',
      id: `U${Date.now()}`, role: UserRole.USER, 
      referralCode: `SP${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      referrerId: ref.id, level: ref.level + 1, wallets: { main: 0, commission: 0, cashback: 0, recharge: 0 },
      totalEarned: 0, status: 'pending', isActivated: false, joinedAt: new Date().toISOString()
    };
    setUsers(prev => [...prev, newUser]);
    setCurrentUser(newUser);
  };

  const handleRecover = (email: string, phone: string, type: 'password' | 'pin'): string | null => {
    const trimmedEmail = email.trim().toLowerCase();
    const trimmedPhone = phone.trim();
    const user = users.find(u => u.email.toLowerCase() === trimmedEmail && u.phone === trimmedPhone);
    if (!user) return null;
    return type === 'password' ? (user.password || null) : user.transactionPin;
  };

  const handleRecharge = (userId: string, amount: number, service: string, pin: string) => {
    const user = users.find(u => u.id === userId);
    if (!user || !user.isActivated) return alert('Please activate your account first.');
    if (user.transactionPin !== pin) return alert('Invalid Transaction PIN');
    if (user.wallets.recharge < amount) return alert('Insufficient Recharge Wallet balance');

    handleTransaction(userId, -amount, 'recharge', 'recharge', `${service} Payment`);
    const cashback = amount * 0.02;
    handleTransaction(userId, cashback, 'cashback', 'recharge', `Cashback for ${service}`);
    alert(`${service} recharge successful!`);
  };

  const placeOrder = (userId: string, productId: string) => {
    const user = users.find(u => u.id === userId);
    const product = products.find(p => p.id === productId);
    if (!user || !user.isActivated) return alert('Please activate your account first.');
    if (!product || user.wallets.main < product.price) return alert('Insufficient Main Wallet balance');

    handleTransaction(userId, -product.price, 'main', 'shopping', `Purchase: ${product.name}`);
    alert('Order placed successfully!');
  };

  const handleTransfer = (senderId: string, recipientEmail: string, amount: number, pin: string) => {
    const sender = users.find(u => u.id === senderId);
    if (!sender) return;
    if (sender.transactionPin !== pin) return alert('Invalid Transaction PIN');

    const recipient = users.find(u => u.email.toLowerCase() === recipientEmail.toLowerCase().trim());
    if (!recipient) return alert('Recipient not found');
    if (senderId === recipient.id) return alert('Cannot transfer to yourself');
    if (sender.wallets.main < amount) return alert('Insufficient balance');

    handleTransaction(senderId, -amount, 'main', 'withdrawal', `Transfer to ${recipient.name}`);
    handleTransaction(recipient.id, amount, 'main', 'add_funds', `Transfer from ${sender.name}`);
    alert('Transfer successful!');
  };

  const handleActivateAccount = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (!user) return;
    if (user.wallets.recharge < mlmConfig.packagePrice) return alert('Insufficient Recharge Wallet balance');

    handleTransaction(userId, -mlmConfig.packagePrice, 'recharge', 'activation', `Package Activation Fee`);
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, isActivated: true, status: 'active' } : u));
    alert('Account Activated Successfully!');
  };

  if (!currentUser) return <Auth onLogin={handleLogin} onSignup={handleSignup} onRecover={handleRecover} />;

  const activeUser = users.find(u => u.id === currentUser.id) || currentUser;

  return (
    <Layout user={activeUser} onLogout={() => setCurrentUser(null)}>
      {activeUser.role === UserRole.ADMIN ? (
        <AdminPanel 
          users={users} 
          transactions={transactions} 
          config={mlmConfig} 
          onUpdateConfig={setMlmConfig}
          paymentRequests={paymentRequests}
          onApprovePayment={handleApprovePayment}
          withdrawalRequests={withdrawalRequests}
          onApproveWithdrawal={handleApproveWithdrawal}
          chatMessages={chatMessages}
          onSendMessage={handleSendMessage}
        />
      ) : (
        <Dashboard 
          user={activeUser} 
          users={users} 
          products={products}
          transactions={transactions.filter(t => t.userId === activeUser.id)} 
          onRecharge={handleRecharge}
          onOrder={placeOrder}
          onTransfer={handleTransfer}
          onActivate={handleActivateAccount}
          packagePrice={mlmConfig.packagePrice}
          qrCode={mlmConfig.qrCode}
          onAddMoney={handleAddMoneyRequest}
          paymentRequests={paymentRequests.filter(r => r.userId === activeUser.id)}
          withdrawalRequests={withdrawalRequests.filter(r => r.userId === activeUser.id)}
          onWithdrawal={handleWithdrawalRequest}
          onUpdateBankDetails={handleUpdateBankDetails}
          chatMessages={chatMessages.filter(m => m.senderId === activeUser.id || m.receiverId === activeUser.id)}
          onSendMessage={handleSendMessage}
        />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';

interface AuthProps {
  onLogin: (email: string, password?: string) => void;
  onSignup: (data: any) => void;
  onRecover: (email: string, phone: string, type: 'password' | 'pin') => string | null;
}

const STATES = [
  "Andaman and Nicobar Islands", "Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar",
  "Chandigarh", "Chhattisgarh", "Dadra and Nagar Haveli and Daman and Diu", "Delhi", "Goa",
  "Gujarat", "Haryana", "Himachal Pradesh", "Jammu and Kashmir", "Jharkhand", "Karnataka",
  "Kerala", "Ladakh", "Lakshadweep", "Madhya Pradesh", "Maharashtra", "Manipur", "Meghalaya",
  "Mizoram", "Nagaland", "Odisha", "Puducherry", "Punjab", "Rajasthan", "Sikkim", "Tamil Nadu",
  "Telangana", "Tripura", "Uttar Pradesh", "Uttarakhand", "West Bengal"
];

const Auth: React.FC<AuthProps> = ({ onLogin, onSignup, onRecover }) => {
  const [view, setView] = useState<'login' | 'signup' | 'recover-password' | 'recover-pin'>('login');
  const [stateSearch, setStateSearch] = useState('');
  const [isStateOpen, setIsStateOpen] = useState(false);
  const [recoveryResult, setRecoveryResult] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    transactionPin: '',
    phone: '',
    state: '',
    referralCode: ''
  });

  const filteredStates = useMemo(() => {
    return STATES.filter(s => s.toLowerCase().includes(stateSearch.toLowerCase()));
  }, [stateSearch]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (view === 'login') {
      onLogin(formData.email, formData.password);
    } else if (view === 'signup') {
      if (formData.transactionPin.length !== 4) {
        alert('Transaction PIN must be exactly 4 digits.');
        return;
      }
      if (!formData.state) {
        alert('Please select your state.');
        return;
      }
      onSignup(formData);
    } else {
      const result = onRecover(formData.email, formData.phone, view === 'recover-password' ? 'password' : 'pin');
      if (result) {
        setRecoveryResult(result);
      } else {
        alert('Verification failed. No user found with these details.');
      }
    }
  };

  const handlePinChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value.replace(/\D/g, '').slice(0, 4);
    setFormData({ ...formData, transactionPin: val });
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
      <div className="bg-white p-10 rounded-[3rem] shadow-2xl w-full max-w-md border border-slate-100 relative overflow-hidden">
        {/* Abstract background element */}
        <div className="absolute -top-24 -right-24 w-48 h-48 bg-blue-500/5 rounded-full blur-3xl"></div>

        <div className="text-center mb-10 relative z-10">
          <div className="mb-6 flex justify-center">
             <div className="relative w-24 h-24">
               <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-2xl">
                 <polygon points="50,5 95,25 95,75 50,95 5,75 5,25" fill="#0077C0" />
                 <path d="M30 40 C 30 30, 70 30, 70 40 L 70 45 C 70 55, 30 55, 30 65 L 30 70 C 30 80, 70 80, 70 70" fill="none" stroke="white" strokeWidth="12" strokeLinecap="round" transform="translate(0, -2)"/>
               </svg>
             </div>
          </div>
          <div className="flex flex-col items-center">
            <h1 className="text-4xl font-black text-[#003B73] tracking-tight leading-none">SmartPay</h1>
            <span className="text-2xl font-bold text-[#4DB8E5] tracking-[0.1em] mt-1">360</span>
          </div>
          <p className="text-slate-400 mt-4 font-bold text-[10px] uppercase tracking-[0.2em]">
            {view === 'login' ? 'Secure Network Login' : 
             view === 'signup' ? 'Create Network Account' :
             view === 'recover-password' ? 'Password Recovery' : 'Transaction PIN Recovery'}
          </p>
        </div>

        {recoveryResult ? (
          <div className="text-center space-y-6 relative z-10">
            <div className="bg-green-50 p-8 rounded-3xl border-2 border-dashed border-green-200">
               <p className="text-[10px] font-black text-green-800 uppercase tracking-widest mb-4">Verification Successful</p>
               <p className="text-slate-500 text-xs font-medium mb-1 uppercase tracking-tighter">Your requested credential is:</p>
               <p className="text-3xl font-black text-blue-600 select-all font-mono tracking-tight">{recoveryResult}</p>
            </div>
            <button 
              onClick={() => { setView('login'); setRecoveryResult(null); }}
              className="w-full py-5 bg-slate-800 text-white font-black rounded-3xl hover:bg-black uppercase tracking-widest text-xs shadow-xl transition-all active:scale-95"
            >
              Back to Login
            </button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 relative z-10">
            {view === 'signup' && (
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">Full Name</label>
                <input
                  type="text"
                  required
                  className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:outline-none transition-all font-bold text-sm"
                  placeholder="Full Name"
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                />
              </div>
            )}

            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">User ID / Email</label>
              <input
                type="email"
                required
                className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:outline-none transition-all font-bold text-sm"
                placeholder="user@smartpay.com"
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
              />
            </div>

            {(view === 'signup' || view === 'recover-password' || view === 'recover-pin') && (
              <div className="grid grid-cols-2 gap-4">
                 <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">Mobile</label>
                  <input
                    type="tel"
                    required
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:outline-none transition-all font-bold text-sm"
                    placeholder="+91"
                    value={formData.phone}
                    onChange={(e) => setFormData({...formData, phone: e.target.value})}
                  />
                </div>
                {view === 'signup' && (
                  <div className="relative">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">State</label>
                    <div 
                      className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl cursor-pointer font-bold text-xs truncate"
                      onClick={() => setIsStateOpen(!isStateOpen)}
                    >
                      {formData.state || "Select State"}
                    </div>
                    {isStateOpen && (
                      <div className="absolute bottom-full left-0 w-full mb-2 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 overflow-hidden">
                        <input 
                          type="text"
                          className="w-full px-4 py-3 border-b border-slate-100 text-xs focus:outline-none bg-slate-50 font-bold"
                          placeholder="Search state..."
                          value={stateSearch}
                          onChange={(e) => setStateSearch(e.target.value)}
                          autoFocus
                        />
                        <div className="max-h-48 overflow-y-auto no-scrollbar">
                          {filteredStates.map(s => (
                            <div 
                              key={s} 
                              className="px-4 py-2.5 hover:bg-blue-50 text-xs font-bold cursor-pointer transition-colors text-slate-700"
                              onClick={() => {
                                setFormData({...formData, state: s});
                                setIsStateOpen(false);
                                setStateSearch('');
                              }}
                            >
                              {s}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {view === 'login' && (
              <div className="space-y-2">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">Password</label>
                  <input
                    type="password"
                    required
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:outline-none transition-all font-bold text-sm"
                    placeholder="••••••••"
                    value={formData.password}
                    onChange={(e) => setFormData({...formData, password: e.target.value})}
                  />
                </div>
                <div className="flex justify-between px-1">
                   <button 
                    type="button" 
                    onClick={() => setView('recover-password')}
                    className="text-[9px] font-black text-slate-400 hover:text-blue-600 transition-colors uppercase tracking-widest"
                   >
                     Forgot Password?
                   </button>
                   <button 
                    type="button" 
                    onClick={() => setView('recover-pin')}
                    className="text-[9px] font-black text-slate-400 hover:text-blue-600 transition-colors uppercase tracking-widest"
                   >
                     Forgot PIN?
                   </button>
                </div>
              </div>
            )}

            {view === 'signup' && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">Password</label>
                  <input
                    type="password"
                    required
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:outline-none transition-all font-bold text-sm"
                    placeholder="••••••••"
                    value={formData.password}
                    onChange={(e) => setFormData({...formData, password: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">Trans. PIN</label>
                  <input
                    type="password"
                    required
                    inputMode="numeric"
                    pattern="\d{4}"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:outline-none transition-all font-bold text-sm text-center tracking-[0.5em]"
                    placeholder="0000"
                    value={formData.transactionPin}
                    onChange={handlePinChange}
                  />
                </div>
              </div>
            )}

            {view === 'signup' && (
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 ml-1">Referral Code</label>
                <input
                  type="text"
                  className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 focus:outline-none transition-all font-bold text-sm"
                  placeholder="SPAY123"
                  value={formData.referralCode}
                  onChange={(e) => setFormData({...formData, referralCode: e.target.value})}
                />
              </div>
            )}

            <button
              type="submit"
              className="w-full py-5 bg-blue-600 text-white font-black rounded-3xl hover:bg-blue-700 active:scale-[0.97] transition-all shadow-2xl shadow-blue-200 mt-4 uppercase tracking-widest text-sm"
            >
              {view === 'login' ? 'Access Account' : 
               view === 'signup' ? 'Register Now' : 'Verify Identity'}
            </button>
          </form>
        )}

        <div className="mt-8 text-center relative z-10">
          <button
            onClick={() => { setView(view === 'login' ? 'signup' : 'login'); setRecoveryResult(null); }}
            className="text-slate-400 text-[10px] font-black hover:text-blue-600 transition-colors uppercase tracking-[0.2em]"
          >
            {view === 'login' ? "Join the network → Sign Up" : "Back to Security → Login"}
          </button>
        </div>

        {view === 'login' && (
          <div className="mt-10 p-6 bg-blue-50 rounded-[2rem] border-2 border-dashed border-blue-200 relative z-10">
            <div className="flex items-center gap-2 mb-3">
               <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
               <p className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Administrator Login Data</p>
            </div>
            <div className="space-y-2">
              <p className="text-xs text-slate-700 font-bold">Email ID: <span className="text-blue-600 select-all font-mono">admin@spay.com</span></p>
              <p className="text-xs text-slate-700 font-bold">Password: <span className="text-blue-600 select-all font-mono">admin123</span></p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Auth;
